'use strict';
/* ====================== Tiện ích ====================== */
const $ = (s, r = document) => r.querySelector(s);
const el = (tag, attrs = {}, ...kids) => {
  const e = document.createElement(tag);
  for (const k in attrs) {
    if (k === 'class') e.className = attrs[k];
    else if (k === 'html') e.innerHTML = attrs[k];
    else if (k.startsWith('on')) e.addEventListener(k.slice(2), attrs[k]);
    else if (typeof attrs[k] === 'boolean') { if (attrs[k]) e.setAttribute(k, ''); }
    else if (attrs[k] != null) e.setAttribute(k, attrs[k]);
  }
  for (const kid of kids.flat()) if (kid != null) e.append(kid.nodeType ? kid : document.createTextNode(kid));
  return e;
};
const fmt = (n) => (Math.round(Number(n) || 0)).toLocaleString('vi-VN');
const money = (n) => fmt(n) + 'đ';

async function api(path, opts = {}) {
  const res = await fetch('/api' + path, {
    method: opts.method || 'GET',
    headers: opts.body ? { 'Content-Type': 'application/json' } : {},
    body: opts.body ? JSON.stringify(opts.body) : undefined,
  });
  let data = null; try { data = await res.json(); } catch {}
  if (!res.ok) throw new Error((data && data.error) || ('Lỗi ' + res.status));
  return data;
}
let toastT;
function toast(msg) {
  const t = $('#toast'); t.textContent = msg; t.classList.add('show');
  clearTimeout(toastT); toastT = setTimeout(() => t.classList.remove('show'), 2200);
}
function modal(title, bodyNode, actions, opts) {
  const root = $('#modalRoot');
  const close = () => { root.innerHTML = ''; };
  const acts = el('div', { class: 'modal-actions' });
  (actions || []).forEach(a => {
    const b = el('button', { class: a.class || '', onclick: () => a.onClick(close) }, a.label);
    acts.append(b);
  });
  const box = el('div', { class: 'modal' + (opts && opts.wide ? ' modal-wide' : '') }, el('h3', {}, title), bodyNode, acts);
  const bg = el('div', { class: 'modal-bg', onclick: (e) => { if (e.target === bg) close(); } }, box);
  root.innerHTML = ''; root.append(bg);
  return close;
}

function resizeImage(file, cb) {
  const reader = new FileReader();
  reader.onload = (e) => {
    const img = new Image();
    img.onload = () => {
      const max = 240; let w = img.width, h = img.height;
      if (w > h) { if (w > max) { h = Math.round(h * max / w); w = max; } }
      else { if (h > max) { w = Math.round(w * max / h); h = max; } }
      const cv = document.createElement('canvas'); cv.width = w; cv.height = h;
      cv.getContext('2d').drawImage(img, 0, 0, w, h);
      cb(cv.toDataURL('image/jpeg', 0.72));
    };
    img.src = e.target.result;
  };
  reader.readAsDataURL(file);
}

