  if (can('debts')) tabs.push({ id: 'debts', label: '💳 Công nợ' });
  if (can('approve')) tabs.push({ id: 'pending', label: '⏳ Chờ duyệt hủy' });
  if (can('users')) tabs.push({ id: 'users', label: '👥 Nhân viên' });
  if (S.user.role === 'owner' && S.pub.role === 'central') tabs.push({ id: 'perms', label: '🔑 Phân quyền' });
  if (can('settings')) tabs.push({ id: 'settings', label: '⚙️ Cài đặt' });
  if (S.user.role === 'owner') tabs.push({ id: 'audit', label: '📋 Nhật ký' });
