  tabs.forEach(t => box.append(el('div', { class: 'tab' + (t.id === S.tab ? ' active' : ''), 'data-id': t.id, onclick: () => { S.tab = t.id; render(); } }, t.label)));
}
function render() {
  buildTabs();
  const v = $('#view'); v.innerHTML = '';
  if (S.tab === 'pos') renderTables(v);
  else if (S.tab === 'stats') renderStats(v);
  else if (S.tab === 'menu') renderMenuMgmt(v);
  else if (S.tab === 'users') renderUsers(v);
  else if (S.tab === 'perms') renderPerms(v);
  else if (S.tab === 'settings') renderSettings(v);
  else if (S.tab === 'debts') renderDebts(v);
  else if (S.tab === 'pending') renderPending(v);
  else if (S.tab === 'audit') renderAudit(v);
}
async function renderDebts(v) {
