    el('strong', { class: 'grow', style: 'font-size:17px' }, '💳 Công nợ (khách thanh toán sau)'),
    el('strong', { style: 'color:#c0392b' }, 'Đang nợ: ' + money(d.total))));
  const range = el('select', { style: 'width:170px' },
    el('option', { value: 'today' }, 'Hôm nay'),
    el('option', { value: 'yesterday' }, 'Hôm qua'),
