    el('option', { value: 'custom' }, 'Tùy chọn khoảng…'));
  const today = new Date().toISOString().slice(0, 10);
  const fromI = el('input', { type: 'date', value: S.debtFrom || today, style: 'width:150px' });
  const toI = el('input', { type: 'date', value: S.debtTo || today, style: 'width:150px' });
  const customBox = el('span', { style: 'display:none;gap:6px;align-items:center' },
    el('span', { class: 'muted' }, 'Từ'), fromI, el('span', { class: 'muted' }, 'đến'), toI);
  range.addEventListener('change', () => { S.debtRange = range.value; customBox.style.display = range.value === 'custom' ? 'inline-flex' : 'none'; });
  range.value = S.debtRange || 'month';
  customBox.style.display = range.value === 'custom' ? 'inline-flex' : 'none';
  const qstr = () => (range.value === 'custom') ? ('range=custom&from=' + fromI.value + '&to=' + toI.value) : ('range=' + range.value);
  v.append(el('div', { class: 'row', style: 'align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:12px' },
    el('span', { class: 'muted', style: 'font-size:13px' }, 'Xuất công nợ theo ngày ăn:'), range, customBox,
    el('button', { onclick: () => { if (range.value === 'custom') { S.debtFrom = fromI.value; S.debtTo = toI.value; } exportReport('debts', qstr()); } }, '⬇️ Xuất Excel')));
  if (!d.debts.length) { v.append(el('div', { class: 'muted' }, 'Không có khoản nợ nào.')); return; }
  const norm = (x) => String(x || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd');
  const normPhone = (x) => String(x || '').replace(/\D/g, '');
  // Gom cac bill CUNG 1 SDT (da chuan hoa) ve chung 1 khach -> de thay tong no that cua tung nguoi.
  // Khong co SDT (vd sep an no, nhan vien chi ghi ten) -> gom theo TEN da chuan hoa, nhung danh dau
  // ro la khop theo TEN (kem chac chan hon SDT, 2 nguoi trung ten van bi gom nham) de chu quan tu kiem tra lai.
  function groupByPhone(list) {
    const map = new Map(); const order = [];
    list.forEach(o => {
      const ph = normPhone(o.customer_phone);
      const nm = norm(o.customer_name).trim();
      let key, matchType;
      if (ph) { key = 'p:' + ph; matchType = 'phone'; }
      else if (nm) { key = 'n:' + nm; matchType = 'name'; }
      else { key = 'o:' + o.order_id; matchType = 'none'; }
      let g = map.get(key);
      if (!g) { g = { phone: o.customer_phone || '', names: [], items: [], origin: 0, paid: 0, remain: 0, matchType }; map.set(key, g); order.push(key); }
      if (o.customer_name && !g.names.includes(o.customer_name)) g.names.push(o.customer_name);
      g.items.push(o);
      g.origin += (o.debt_origin != null ? o.debt_origin : o.total) || 0;
      g.paid += (o.debt_paid || 0);
