    });
    return order.map(k => map.get(k));
  }
  const info = el('div', { class: 'muted', style: 'margin:2px 0 8px' });
  const search = el('input', { type: 'search', placeholder: '🔍 Tìm theo tên khách hoặc SĐT...', style: 'width:100%;max-width:440px;padding:9px 11px;font-size:15px;border:1px solid #ccc;border-radius:8px', oninput: (e) => draw(e.target.value) });
  const holder = el('div', { class: 'section', style: 'margin-top:6px' });
  v.append(search, info, holder);
  function billRow(o) {
    return el('tr', {},
      el('td', {}, o.customer_name || '—'), el('td', {}, o.customer_phone || ''), el('td', { class: 'muted' }, o.customer_note || ''),
      el('td', {}, (o.table_names || '') + ' · ' + o.code), el('td', { class: 'muted' }, o.paid_at || ''),
