    const list = k ? d.debts.filter(o => norm(o.customer_name).includes(k) || norm(o.customer_phone).replace(/\s/g, '').includes(kd)) : d.debts;
    const groups = groupByPhone(list);
    const sub = list.reduce((s, o) => s + (o.debt != null ? o.debt : o.total), 0);
