    const t = el('table', { class: 'grid' }, el('tr', {}, el('th', {}, 'Khách'), el('th', {}, 'SĐT'), el('th', {}, 'Ghi chú'), el('th', {}, 'Bàn / Mã'), el('th', {}, 'Ngày ăn'), el('th', { class: 'right' }, 'Nợ gốc'), el('th', { class: 'right' }, 'Đã thu'), el('th', { class: 'right' }, 'Còn nợ'), el('th', {}, '')));
    groups.forEach(g => {
      if (g.items.length === 1) { t.append(billRow(g.items[0])); return; }
      // Nhieu bill cung 1 khach -> hien DAY DU tung lan an no (kem dung ngay), roi den dong TONG cuoi cung
      // (KHONG an bot chi tiet - can biet chinh xac tung ngay an no la ngay nao).
