        : ('↳ Tổng ' + (g.names.join(' / ') || '—'));
      t.append(el('tr', { style: 'font-weight:600;background:var(--bg)' },
        el('td', {}, nameLbl), el('td', {}, g.phone), el('td', { class: 'muted', style: 'font-size:12px' }, g.items.length + ' bill'), el('td', {}), el('td', {}),
        el('td', { class: 'right' }, money(g.origin)),
        el('td', { class: 'right', style: (g.paid ? 'color:#1d7a35' : '') }, g.paid ? money(g.paid) : '—'),
        el('td', { class: 'right', style: 'color:#c0392b' }, money(g.remain)),
        el('td', {})));
    });
    holder.append(t);
  }
  draw('');
  // Cac khoan DA THU XONG gan day -> de xem lai / huy neu bam nham
  const done = d.done || [];
  if (done.length) {
    const wrap = el('div', { class: 'section', style: 'margin-top:16px' });
    const head = el('div', { class: 'row', style: 'align-items:center;cursor:pointer' },
      el('strong', { class: 'grow', style: 'font-size:15px' }, '✅ Đã thu xong gần đây (' + done.length + ')'),
      el('span', { class: 'muted', style: 'font-size:12px' }, 'bấm để xem / sửa lại nếu ghi nhầm'));
    const inner = el('div', { style: 'display:none;margin-top:8px' });
    head.onclick = () => { inner.style.display = inner.style.display === 'none' ? 'block' : 'none'; };
    const t2 = el('table', { class: 'grid' }, el('tr', {}, el('th', {}, 'Khách'), el('th', {}, 'Bàn / Mã'), el('th', {}, 'Ngày ăn'), el('th', { class: 'right' }, 'Đã thu'), el('th', {}, 'Các lần thu'), el('th', {}, '')));
    done.forEach(o => t2.append(el('tr', {},
      el('td', {}, o.customer_name || '—'), el('td', {}, (o.table_names || '') + ' · ' + o.code), el('td', { class: 'muted' }, o.paid_at || ''),
      el('td', { class: 'right' }, money(o.debt_paid)),
      el('td', { class: 'muted', style: 'font-size:12px' }, (o.payments || []).map(pm => String(pm.paid_at || '').slice(0, 10) + ' ' + (pm.cash ? 'TM' : '') + (pm.transfer ? 'CK' : '')).join(' · ')),
      el('td', {}, el('button', { class: 'ghost', onclick: () => settleDebt(o) }, 'Xem / sửa')))));
    inner.append(t2); wrap.append(head, inner); v.append(wrap);
  }
}
async function renderPending(v) {
  v.innerHTML = 'Đang tải...';
