  if (!bills.length) { v.append(el('div', { class: 'muted' }, 'Không có bill nào chờ duyệt.')); return; }
  bills.forEach(b => {
    const box = el('div', { class: 'section', style: 'margin-bottom:12px' },
      el('div', { class: 'row', style: 'align-items:center;margin-bottom:6px' },
        el('strong', { class: 'grow' }, (b.table_names || 'Bàn') + ' · ' + b.code + (b.status === 'paid' ? ' · đã thanh toán' : ' · đang mở')),
        el('span', { class: 'muted', style: 'font-size:13px' }, (b.staff_name || '') + (b.paid_at ? ' · ' + b.paid_at : ''))));
    b.pending_items.forEach(it => box.append(el('div', { class: 'row', style: 'align-items:center;padding:6px 0;border-top:1px solid var(--line);gap:8px' },
      el('div', { class: 'grow' }, '🗑 ' + it.name + ' ×' + it.qty + ' (' + money(it.price * it.qty) + ')'),
      el('button', { class: 'danger', onclick: async () => { try { await api('/order-items/' + it.id + '/approve-del', { method: 'POST' }); toast('Đã duyệt hủy món'); renderPending($('#view')); } catch (e) { toast(e.message); } } }, 'Duyệt hủy'),
      el('button', { onclick: async () => { try { await api('/order-items/' + it.id + '/reject-del', { method: 'POST' }); toast('Đã giữ lại (tính tiền)'); renderPending($('#view')); } catch (e) { toast(e.message); } } }, 'Giữ lại (tính tiền)'))));
    v.append(box);
