/* ====================== Polling đồng bộ ====================== */
let pollT;
function startPolling() {
  clearInterval(pollT);
  let ptick = 0;
  pollT = setInterval(async () => {
    ptick++;
    if (ptick % 8 === 0) {
      try {
        const me = await api('/me');
        const curP = JSON.stringify([...((S.user && S.user.perms) || [])].sort());
        const newP = JSON.stringify([...(me.perms || [])].sort());
        S.user = me;
        if (curP !== newP) {
          buildTabs();
          // chi roi tab khi tab hien tai THUC SU mat quyen (tranh chop man hinh)
