function payOrder(order) {
  const due = order.payable != null ? order.payable : order.total;
  const num = (x) => Math.max(0, Math.round(Number(x) || 0));
  const cashIn = el('input', { type: 'number', min: '0', value: String(due), style: 'width:100%;text-align:right' });
  const transIn = el('input', { type: 'number', min: '0', value: '0', style: 'width:100%;text-align:right' });
  const cname = el('input', { placeholder: 'Tên khách nợ' });
  const cphone = el('input', { placeholder: 'Số điện thoại' });
  const cnote = el('input', { placeholder: 'Ghi chú (hẹn trả, địa chỉ…)' });
  const debtBox = el('div', { style: 'display:none;border:1px dashed var(--line2);border-radius:8px;padding:8px;margin-top:6px' },
    el('div', { class: 'muted', style: 'font-size:12px;margin-bottom:6px' }, 'Còn nợ → nhập thông tin khách:'),
    el('div', { class: 'field' }, el('label', {}, 'Tên khách'), cname),
    el('div', { class: 'field' }, el('label', {}, 'Số điện thoại'), cphone),
    el('div', { class: 'field' }, el('label', {}, 'Ghi chú'), cnote));
  const debtRow = el('div', { class: 'row', style: 'justify-content:space-between;padding:9px 11px;border-radius:8px;margin-top:8px;font-weight:600' });
  const totalLbl = el('div', { style: 'font-size:15px;color:var(--muted);margin-top:6px' });
  const upd = () => {
    const cash = num(cashIn.value), transfer = num(transIn.value);
    const debt = Math.max(0, due - cash - transfer);
    debtBox.style.display = debt > 0 ? 'block' : 'none';
    debtRow.style.background = debt > 0 ? '#fff7ed' : '#e7f6ee';
    debtRow.style.color = debt > 0 ? '#9a3412' : '#1a7f4b';
    debtRow.innerHTML = '';
    debtRow.append(el('span', {}, debt > 0 ? '📝 Còn nợ' : '✓ Đã đủ tiền'), el('span', {}, money(debt)));
    totalLbl.textContent = 'Khách phải trả: ' + money(due) + (cash + transfer > due ? ' (đang nhập vượt!)' : '');
  };
  cashIn.addEventListener('input', upd); transIn.addEventListener('input', upd);
  const qbtn = (lbl, fn) => el('button', { class: 'ghost', style: 'flex:1;font-size:12px', onclick: () => { fn(); upd(); } }, lbl);
  const quick = el('div', { class: 'row', style: 'gap:6px;margin-top:8px' },
    qbtn('Tất cả tiền mặt', () => { cashIn.value = String(due); transIn.value = '0'; }),
    qbtn('Tất cả CK', () => { cashIn.value = '0'; transIn.value = String(due); }),
    qbtn('Đủ tiền (hết nợ)', () => { const t = num(transIn.value); cashIn.value = String(Math.max(0, due - t)); }));
  const ln = (l, v) => el('div', { class: 'row', style: 'justify-content:space-between' }, el('span', { class: 'muted' }, l), el('span', {}, v));
  const brk = el('div', { style: 'margin-bottom:8px' }, ln('Tạm tính', money(order.subtotal)));
  if (order.discount_amount) brk.append(ln('Khuyến mại ' + (order.discount_pct || 0) + '%', '-' + money(order.discount_amount)));
  (order.tax_breakdown || []).forEach(t => brk.append(ln('Thuế VAT ' + t.rate + '%', '+' + money(t.amount))));
  if (order.deposit) { brk.append(ln('Tổng đơn', money(order.total))); brk.append(ln('Tiền cọc đã đặt', '-' + money(order.deposit))); }
  const body = el('div', {}, brk,
    order.has_pending ? el('div', { style: 'font-size:12px;color:#c0392b;margin-top:4px' }, '⚠ Có món chờ duyệt hủy — đã trừ khỏi bill.') : null,
    totalLbl,
    el('div', { class: 'field', style: 'margin-top:8px' }, el('label', {}, '💵 Tiền mặt'), cashIn),
    el('div', { class: 'field' }, el('label', {}, '🏦 Chuyển khoản'), transIn),
    quick, debtRow, debtBox);
  upd();
  modal('Thanh toán — ' + (order.table_names || 'Bàn'), body, [
    { label: 'Hủy', onClick: (c) => c() },
    { label: '✔ Xác nhận & in', class: 'primary', onClick: async (c) => {
      const cash = num(cashIn.value), transfer = num(transIn.value);
      const debt = Math.max(0, due - cash - transfer);
      if (debt > 0 && !cname.value.trim()) return toast('Còn nợ — hãy nhập tên khách');
      try {
        const paid = await api('/orders/' + order.id + '/pay', { method: 'POST', body: { paid_cash: cash, paid_transfer: transfer, customer_name: cname.value.trim(), customer_phone: cphone.value.trim(), customer_note: cnote.value.trim() } });
        c(); toast(debt > 0 ? ('Đã thu ' + money(Math.min(cash + transfer, due)) + ', còn nợ ' + money(debt)) : ('Đã thanh toán ' + money(due))); printReceipt(paid, false); renderTables($('#view'));
      } catch (e) { toast(e.message); }
    } },
  ]);
}
function nowLocalInput() { const p2 = n => String(n).padStart(2, '0'); const d = new Date(); return d.getFullYear() + '-' + p2(d.getMonth() + 1) + '-' + p2(d.getDate()) + 'T' + p2(d.getHours()) + ':' + p2(d.getMinutes()); }
function settleDebt(o) {
