    el('div', { class: 'field' }, el('label', {}, '💵 Tiền mặt'), cashIn),
    el('div', { class: 'field' }, el('label', {}, '🏦 Chuyển khoản'), transIn),
    el('div', { class: 'row', style: 'gap:6px;margin-top:2px' },
