      try {
        const r = await api('/orders/' + o.order_id + '/settle-debt', { method: 'POST', body: { pay_cash: c0, pay_transfer: t0, paid_at: dateIn.value } });
        c(); toast(r.remaining > 0 ? ('Đã thu ' + money(r.paid) + ', còn nợ ' + money(r.remaining)) : 'Đã thu đủ, đóng khoản nợ'); renderDebts($('#view'));
      } catch (e) { toast(e.message); }
    } },
  ]);
