/* ====================== In hóa đơn ====================== */
function buildReceiptHtml(order, provisional) {
  const P = S.pub;
  const paper = P.paper_size === '58' ? '58mm' : '80mm';
  const bw = P.paper_size === '58' ? '40mm' : '66mm';
  const sub = order.subtotal != null ? order.subtotal : order.items.reduce((a, i) => a + (i.del_req ? 0 : i.price * i.qty), 0);
  const discAmt = order.discount_amount || 0;
  const dpct = order.discount_pct || 0;
  const taxAmt = order.tax_amount || 0;
  const taxBrk = order.tax_breakdown && order.tax_breakdown.length ? order.tax_breakdown : (taxAmt ? [{ rate: order.tax_pct || 0, amount: taxAmt }] : []);
  const total = order.total != null ? order.total : (Math.max(0, sub - discAmt) + taxAmt);
  const deposit = order.deposit || 0;
  const payable = Math.max(0, total - deposit);
  const escH = (x) => String(x == null ? '' : x).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
