function doPrint(html) {
  const desk = window.qlnhDesktop || window.panel;
  if (desk && desk.printReceipt) {
    desk.printReceipt(html).then(r => { if (r && r.ok === false) toast('Lỗi in: ' + (r.reason || 'kiểm tra máy in')); else toast('🖨️ Đã gửi lệnh in'); }).catch(() => toast('Lỗi in'));
    return;
  }
  const win = window.open('', '_blank', 'width=400,height=640');
  if (!win) { toast('Trình duyệt chặn cửa sổ in. Hãy cho phép popup.'); return; }
  win.document.write(html); win.document.close();
  win.focus(); setTimeout(() => { win.print(); }, 300);
}
function printReceipt(order, provisional) {
  const html = buildReceiptHtml(order, provisional);
  const frame = el('iframe', { style: 'width:330px;max-width:100%;height:58vh;border:0;background:#fff;border-radius:4px' });
  frame.srcdoc = html;
