    { label: '🖨️ In', class: 'primary', onClick: (c) => { c(); doPrint(html); } },
  ]);
}

/* ====================== Gộp / Tách / Chuyển bàn ====================== */
async function showTableOps(order) {
  let tables = await api('/tables');
  const freeTables = tables.filter(t => !t.open);
  const busyOthers = tables.filter(t => t.open && t.open.order_id !== order.id);

  const sel = (list, ph) => { const s = el('select', {}, el('option', { value: '' }, ph)); list.forEach(t => s.append(el('option', { value: JSON.stringify(t) }, t.name + (t.open ? ' (' + money(t.open.total) + ')' : '')))); return s; };

  const transSel = sel(freeTables, '— chọn bàn trống —');
  const ownIds = [order.table_id].concat(String(order.extra_tables || '').split(',').map(Number).filter(Boolean));
  const mergeCandidates = tables.filter(t => !(t.open && t.open.order_id === order.id) && !ownIds.includes(t.id));
  const mergeSel = sel(mergeCandidates, '— chọn bàn để gộp (trống hoặc có khách) —');

  const splitBox = el('div', {});
  order.items.forEach(it => {
    splitBox.append(el('label', { style: 'display:flex;gap:8px;align-items:center;font-size:14px;color:#1c2024' },
      el('input', { type: 'checkbox', style: 'width:auto', value: it.id }), `${it.name} ×${it.qty}`));
  });
  const splitSel = sel(freeTables, '— bàn trống để tách sang —');

  const body = el('div', {},
    el('div', { class: 'section', style: 'padding:12px;margin-bottom:10px' }, el('strong', {}, 'Chuyển bàn'), el('div', { style: 'margin-top:6px' }, transSel)),
    el('div', { class: 'section', style: 'padding:12px;margin-bottom:10px' }, el('strong', {}, 'Gộp bàn'), el('p', { class: 'muted', style: 'font-size:12px;margin:4px 0' }, 'Gộp bàn khác (kể cả BÀN TRỐNG) vào đơn này — dùng chung một hóa đơn'), mergeSel),
    el('div', { class: 'section', style: 'padding:12px;margin-bottom:0' }, el('strong', {}, 'Tách bàn'), splitBox, el('div', { style: 'margin-top:6px' }, splitSel)));

  modal('Thao tác bàn — ' + (order.table_names || ''), body, [
    { label: 'Đóng', onClick: (c) => c() },
    {
      label: 'Thực hiện', class: 'primary', onClick: async (c) => {
        try {
          if (transSel.value) { const t = JSON.parse(transSel.value); await api('/orders/' + order.id + '/transfer', { method: 'POST', body: { table_id: t.id } }); toast('Đã chuyển sang ' + t.name); }
          else if (mergeSel.value) { const t = JSON.parse(mergeSel.value); await api('/orders/' + order.id + '/merge', { method: 'POST', body: { table_id: t.id } }); toast('Đã gộp ' + t.name); }
          else if (splitSel.value) {
            const ids = [...splitBox.querySelectorAll('input:checked')].map(i => Number(i.value));
            const t = JSON.parse(splitSel.value);
            await api('/orders/' + order.id + '/split', { method: 'POST', body: { item_ids: ids, table_id: t.id } }); toast('Đã tách sang ' + t.name);
          } else { toast('Chưa chọn thao tác'); return; }
          c(); openOrder(order.table_id);
        } catch (e) { toast(e.message); }
      }
    },
  ]);
}

