async function exportReport(type, q) {
  try {
    const res = await fetch('/api/report?type=' + type + '&' + q, { credentials: 'same-origin' });
    if (!res.ok) { toast('Lỗi xuất báo cáo (' + res.status + ')'); return; }
    const blob = await res.blob();
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = (type === 'daily' ? 'tonghop-theo-ngay' : (type === 'debts' ? 'cong-no' : 'chitiet-hoadon-mathang')) + '.xlsx';
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 5000);
    toast('Đã xuất báo cáo Excel');
  } catch (e) { toast('Lỗi xuất: ' + (e.message || e)); }
}

