async function renderMenuMgmt(v) {
  v.innerHTML = 'Đang tải...';
  const menu = await api('/menu');
  S.menu = menu;
  v.innerHTML = '';
  const head = el('div', { class: 'row', style: 'align-items:center;margin-bottom:12px' },
    el('strong', { class: 'grow', style: 'font-size:17px' }, '🍜 Quản lý thực đơn'),
    el('button', { onclick: () => editCategory(null) }, '+ Danh mục'),
    el('button', { class: 'primary', onclick: () => editItem(null, menu.categories) }, '+ Món'));
  v.append(head);
  const search = el('input', { class: 'menu-search', type: 'search', placeholder: '🔎 Tìm món theo tên trong toàn bộ thực đơn…' });
  v.append(search);
  const norm = (str) => (str || '').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/đ/g, 'd').toLowerCase();
  const mainOrder = []; const subsByMain = {};
  menu.categories.forEach(c => { const m = c.parent || 'Khác'; if (!subsByMain[m]) { subsByMain[m] = []; mainOrder.push(m); } subsByMain[m].push(c); });
  let activeMain = mainOrder[0] || '';
  const mainRow = el('div', { class: 'cats' });
  const bodyBox = el('div', {});
  v.append(mainRow, bodyBox);
  const card = (i) => el('div', { class: 'menu-card' },
    el('div', { class: 'mc-body' },
      el('div', { class: 'mc-name', title: (i.code ? i.code + ' · ' : '') + i.name }, i.name),
      el('div', { class: 'mc-price' }, money(i.price) + (i.unit ? ' / ' + i.unit : ''))),
    el('div', { class: 'mc-acts' },
      el('button', { class: 'ghost', title: 'Sửa', onclick: () => editItem(i, menu.categories) }, '✏️'),
      el('button', { class: 'ghost', style: 'color:#c0392b', title: 'Xóa', onclick: () => delItem2(i) }, '🗑️')));
  const countMain = (m) => subsByMain[m].reduce((a, c) => a + menu.items.filter(i => i.category_id === c.id).length, 0);
  const drawMains = () => { mainRow.innerHTML = ''; mainOrder.forEach(m => mainRow.append(el('div', { class: 'cat' + (m === activeMain ? ' active' : ''), onclick: () => { activeMain = m; drawMains(); drawBody(); } }, m + ' (' + countMain(m) + ')'))); };
  const drawBody = (q) => {
    bodyBox.innerHTML = '';
    if (q) {
      const items = menu.items.filter(i => norm(i.name).includes(norm(q)));
      const grid = el('div', { class: 'menu-mgmt-grid' });
      if (!items.length) grid.append(el('div', { class: 'muted', style: 'font-size:13px;padding:4px' }, 'Không tìm thấy.'));
      items.forEach(i => grid.append(card(i)));
      bodyBox.append(el('div', { class: 'section', style: 'margin-bottom:12px' }, el('h2', {}, 'Kết quả tìm: ' + items.length + ' món'), grid));
      return;
    }
    (subsByMain[activeMain] || []).forEach(c => {
      const items = menu.items.filter(i => i.category_id === c.id);
      const grid = el('div', { class: 'menu-mgmt-grid' });
      if (!items.length) grid.append(el('div', { class: 'muted', style: 'font-size:13px;padding:4px' }, 'Chưa có món.'));
      items.forEach(i => grid.append(card(i)));
      bodyBox.append(el('div', { class: 'section', style: 'margin-bottom:12px' },
        el('div', { class: 'row', style: 'align-items:center;margin-bottom:8px' },
          el('h2', { class: 'grow', style: 'margin:0' }, c.name + ' (' + items.length + ')'),
          el('button', { class: 'ghost', onclick: () => editCategory(c) }, '✏️ Sửa danh mục')),
        grid));
    });
  };
  search.addEventListener('input', () => { drawMains(); drawBody(search.value.trim()); });
  drawMains(); drawBody();
}
