    el('p', { style: 'color:#c0392b;font-size:13px' }, '⚠ XÓA SẠCH mọi đơn hàng, công nợ, lịch sử — KHÔNG khôi phục được. Để xóa hết, hãy làm trên CẢ máy chủ và máy quầy.'),
    el('div', { class: 'field' }, el('label', {}, 'Lớp 1 — Nhập mật khẩu của bạn'), pw),
    el('div', { class: 'field' }, el('label', {}, 'Lớp 2 — Gõ chữ XÓA để xác nhận'), cf));
  modal('Xác nhận xóa dữ liệu', body, [
    { label: 'Hủy', onClick: (c) => c() },
    { label: '🗑 Xóa sạch', class: 'danger', onClick: async (c) => {
        if (!pw.value) return toast('Nhập mật khẩu');
        if (!cf.value.trim()) return toast('Gõ chữ XÓA để xác nhận');
        try { await api('/admin/wipe-data', { method: 'POST', body: { password: pw.value, confirm: cf.value } }); c(); toast('Đã xóa sạch dữ liệu bán hàng'); render(); } catch (e) { toast(e.message); }
      } },
  ]);
}
function updatesSection() {
  return el('div', { class: 'section' }, el('h2', {}, '⬆️ Cập nhật phần mềm'),
    el('p', { class: 'muted', style: 'font-size:13px;margin-top:0' }, 'App tự cập nhật qua internet (GitHub). Mỗi lần mở app và mỗi 30 phút, máy tự kiểm tra bản mới, tải về rồi hỏi “Cài & khởi động lại”. Khách ở xa không cần làm gì.'),
    el('p', { class: 'muted', style: 'font-size:12px' }, 'Người phát triển: tăng số phiên bản rồi chạy “dang-len-github.bat” để đẩy bản mới lên — máy khách sẽ tự nhận.'),
    (window.panel && window.panel.checkUpdate ? el('button', { class: 'primary', onclick: async () => { toast('Đang kiểm tra cập nhật…'); try { const r = await window.panel.checkUpdate(); toast(r.msg || 'Đã kiểm tra'); } catch (e) { toast('Lỗi kiểm tra'); } } }, '⬆️ Kiểm tra cập nhật ngay') : null));
}
async function printerSection() {
  const sec = el('div', { class: 'section' }, el('h2', {}, '🖨️ Máy in hóa đơn'),
    el('p', { class: 'muted', style: 'font-size:13px;margin-top:0' }, 'Chọn máy in để in hóa đơn thẳng (không hỏi lại). Bấm "Quét lại" nếu vừa cắm máy in mới hoặc máy in mới bật.'));
  const sel = el('select', {});
  const load = async () => {
    sel.innerHTML = '';
    sel.append(el('option', { value: '' }, '(Máy in mặc định của Windows)'));
    let printers = []; try { printers = await window.panel.listPrinters(); } catch (e) {}
    printers.forEach(p => sel.append(el('option', { value: p.name }, (p.displayName || p.name) + (p.isDefault ? ' (mặc định)' : ''))));
    let cur = ''; try { cur = (await window.panel.getPrintConfig()).printer || ''; } catch (e) {}
    sel.value = cur;
  };
  await load();
  sec.append(el('div', { class: 'field' }, el('label', {}, 'Chọn máy in (' + (sel.length - 1) + ' máy tìm thấy)'), sel),
    el('div', { class: 'row', style: 'gap:8px' },
      el('button', { onclick: load }, '🔄 Quét lại máy in'),
      el('button', { class: 'primary', onclick: async () => { try { await window.panel.savePrintConfig({ printer: sel.value }); toast('Đã lưu máy in'); } catch (e) { toast('Lỗi lưu'); } } }, 'Lưu máy in')));
  return sec;
}
async function connSection() {
  let info = { ips: [], port: 4000, sync_key: '' };
  try { info = await api('/conn-info'); } catch (e) {}
  const copy = (txt, msg) => { try { navigator.clipboard.writeText(txt); toast(msg || 'Đã sao chép'); } catch (e) { toast('Không sao chép được'); } };
  const lbl = (t) => el('label', { style: 'font-size:13px;color:var(--muted);margin-top:10px;display:block' }, t);
  const sec = el('div', { class: 'section' }, el('h2', {}, '🔌 Kết nối máy quầy'),
    el('p', { class: 'muted', style: 'font-size:13px;margin-top:0' }, 'Nhập các thông tin dưới đây vào mục Cài đặt của app máy quầy để máy quầy kết nối và tự đồng bộ về máy chủ.'),
    lbl('Địa chỉ máy chủ (cùng wifi/LAN) — cổng ' + info.port));
  if (!info.ips.length) sec.append(el('div', { class: 'muted', style: 'font-size:13px' }, 'Không tìm thấy địa chỉ mạng.'));
  info.ips.forEach(ip => {
    const addr = ip + ':' + info.port;
    sec.append(el('div', { class: 'conn-row' }, el('code', {}, addr),
      el('button', { class: 'ghost', onclick: () => copy(addr, 'Đã sao chép địa chỉ') }, 'Sao chép')));
  });
  sec.append(lbl('Khóa đồng bộ (giữ bí mật)'));
  const MASK = '••••••••••••••••••••';
  const keyCode = el('code', { style: 'word-break:break-all' }, MASK);
  let keyShown = false;
  const eyeBtn = el('button', { class: 'ghost', title: 'Hiện/ẩn khóa', onclick: () => {
    keyShown = !keyShown;
    keyCode.textContent = keyShown ? (info.sync_key || '—') : MASK;
    eyeBtn.textContent = keyShown ? '🙈' : '👁️';
  } }, '👁️');
  sec.append(el('div', { class: 'conn-row' }, keyCode,
    el('span', { style: 'display:flex;gap:6px' }, eyeBtn,
      el('button', { class: 'ghost', onclick: () => copy(info.sync_key, 'Đã sao chép khóa') }, 'Sao chép'))));
  if (window.panel && window.panel.tunnelStatus) {
    const tStat = el('span', { class: 'muted', style: 'font-size:13px' }, 'Đang tắt');
    const tUrl = el('code', { style: 'word-break:break-all' }, '');
    const tBtn = el('button', { class: 'primary' }, 'Bật truy cập internet');
    const tBox = el('div', { style: 'display:none;margin-top:6px' },
      el('div', { class: 'conn-row' }, tUrl, el('button', { class: 'ghost', onclick: () => copy(tUrl.textContent, 'Đã sao chép link') }, 'Sao chép')));
    const refresh = async () => {
      let st = {}; try { st = await window.panel.tunnelStatus(); } catch (e) {}
      const mode = st && st.fixed ? ' · link cố định' : '';
      if (st && st.running) { tStat.textContent = 'Đang bật' + mode; tBtn.textContent = 'Tắt truy cập internet'; tUrl.textContent = st.url || ''; tBox.style.display = st.url ? 'block' : 'none'; }
      else { tStat.textContent = 'Đang tắt' + mode; tBtn.textContent = 'Bật truy cập internet'; tBox.style.display = 'none'; }
    };
    tBtn.addEventListener('click', async () => {
      let st = {}; try { st = await window.panel.tunnelStatus(); } catch (e) {}
      tBtn.disabled = true;
      if (st && st.running) { try { await window.panel.tunnelStop(); } catch (e) {} }
      else { toast('Đang bật (lần đầu tải công cụ ~35MB)…'); try { const r = await window.panel.tunnelStart(); if (r && !r.ok) toast(r.msg || 'Lỗi bật'); } catch (e) { toast('Lỗi bật'); } }
      tBtn.disabled = false; refresh();
    });
    sec.append(lbl('Truy cập internet (1 chạm) — cho máy quầy ở xa'),
      el('div', { class: 'row', style: 'align-items:center;gap:10px' }, tStat, el('div', { class: 'grow' }), tBtn), tBox);
    // Nâng cao: link CỐ ĐỊNH (không đổi khi bật/tắt) bằng Cloudflare Tunnel có token
    if (window.panel.tunnelSaveConfig) {
      const cfHost = el('input', { placeholder: 'vd: https://quan.ten-mien-cua-ban.com', style: 'width:100%' });
      const cfToken = el('input', { placeholder: 'dán token Cloudflare Tunnel', style: 'width:100%' });
      try { const c = await window.panel.tunnelGetConfig(); cfHost.value = c.hostname || ''; if (c.hasToken) cfToken.placeholder = '•••• đã lưu — để trống nếu giữ nguyên'; } catch (e) {}
      sec.append(el('details', { style: 'margin-top:12px' },
        el('summary', { style: 'cursor:pointer;font-size:13px;color:var(--accent-d)' }, '⚙️ Link cố định — không đổi khi bật/tắt (nâng cao)'),
        el('p', { class: 'muted', style: 'font-size:12px' }, 'Cần một tên miền đã trỏ vào Cloudflare và tạo Tunnel trong Cloudflare Zero Trust (làm 1 lần). Dán địa chỉ cố định + token vào đây; sau đó Bật/Tắt sẽ KHÔNG đổi link. Để trống mục này thì dùng link tạm như cũ.'),
        lbl('Địa chỉ cố định (hostname)'), cfHost,
        lbl('Token Cloudflare Tunnel'), cfToken,
        el('div', { class: 'row', style: 'gap:8px;margin-top:8px' },
          el('button', { class: 'primary', onclick: async () => { try { await window.panel.tunnelSaveConfig({ hostname: cfHost.value.trim(), token: cfToken.value.trim() }); cfToken.value = ''; cfToken.placeholder = '•••• đã lưu — để trống nếu giữ nguyên'; toast('Đã lưu link cố định. Bật lại để áp dụng.'); refresh(); } catch (e) { toast('Lỗi lưu'); } } }, 'Lưu link cố định'),
          el('button', { class: 'ghost', onclick: async () => { try { await window.panel.tunnelSaveConfig({ clearToken: true, hostname: cfHost.value.trim() }); cfToken.placeholder = 'dán token Cloudflare Tunnel'; toast('Đã chuyển về link tạm'); refresh(); } catch (e) {} } }, 'Quay về link tạm'))));
    }
    refresh();
  } else {
    sec.append(el('p', { class: 'muted', style: 'font-size:12px;margin-top:10px' }, 'Truy cập internet qua đường link 1 chạm: bật trong cửa sổ “Thông tin kết nối” của app máy chủ.'));
  }
  return sec;
}
async function emergencyBackup() {
  if (!confirm('Xuất toàn bộ dữ liệu ra Excel và gửi về email đã cấu hình?')) return;
  toast('Đang gửi...');
  try { const r = await api('/backup/email', { method: 'POST' }); toast('Đã gửi sao lưu tới ' + r.to); } catch (e) { toast('Lỗi gửi: ' + e.message); }
}

/* ====================== CHỦ QUÁN: Nhật ký ====================== */
async function renderAudit(v) {
  v.innerHTML = 'Đang tải...';
  const logs = await api('/audit');
  v.innerHTML = '';
  v.append(el('strong', { style: 'font-size:17px' }, '📋 Nhật ký hoạt động (500 dòng gần nhất)'));
  const t = el('table', { class: 'grid', style: 'margin-top:10px' }, el('tr', {}, el('th', {}, 'Thời gian'), el('th', {}, 'Người'), el('th', {}, 'Hành động'), el('th', {}, 'Chi tiết')));
  logs.forEach(l => t.append(el('tr', {}, el('td', {}, l.created_at), el('td', {}, l.username || ''), el('td', {}, l.action), el('td', { class: 'muted' }, l.detail || ''))));
  v.append(el('div', { class: 'section', style: 'margin-top:10px' }, t));
}

function licenseSection() {
  const L = S.license || {};
  const st = L.activated ? ('✓ Đã kích hoạt' + (L.permanent ? ' (vĩnh viễn)' : (L.exp ? ' — hết hạn ' + new Date(L.exp).toLocaleDateString('vi-VN') : ''))) : ('Đang dùng thử — còn ' + (L.trial_days_left != null ? L.trial_days_left : '?') + ' ngày');
  return el('div', { class: 'section' }, el('h2', {}, '🔑 Bản quyền (theo mã máy)'),
    el('p', { class: 'muted', style: 'font-size:13px;margin-top:0' }, 'Trạng thái: ', el('b', { style: 'color:' + (L.activated ? 'var(--green)' : '#9a6700') }, st)),
    el('div', { style: 'font-size:13px' }, 'Mã máy: ', el('b', { style: 'user-select:all;letter-spacing:1px' }, L.machine_id || '—')),
    el('button', { class: 'primary', style: 'margin-top:8px', onclick: () => licenseModal() }, 'Xem mã máy / Nhập mã kích hoạt'));
}
function licenseModal() {
  const L = S.license || {};
  const keyIn = el('textarea', { rows: '3', placeholder: 'Dán mã kích hoạt vào đây', style: 'width:100%;padding:8px;border:1px solid var(--line2);border-radius:8px;box-sizing:border-box;font-family:monospace;font-size:12px' });
  const body = el('div', {},
    el('p', { class: 'muted', style: 'font-size:13px;margin-top:0' }, L.activated ? ('✓ Đã kích hoạt' + (L.permanent ? ' — vĩnh viễn.' : '.')) : ('Đang dùng thử — còn ' + (L.trial_days_left != null ? L.trial_days_left : '?') + ' ngày.')),
    el('div', { style: 'font-size:12px;color:var(--muted);margin-bottom:3px' }, 'MÃ MÁY (gửi cho nhà cung cấp để lấy mã kích hoạt):'),
    el('div', { style: 'font-size:18px;font-weight:700;letter-spacing:1px;background:#f1f2f4;border-radius:8px;padding:10px;text-align:center;user-select:all;cursor:copy', title: 'Bấm để copy', onclick: () => { try { navigator.clipboard.writeText(L.machine_id || ''); toast('Đã copy mã máy'); } catch (e) {} } }, L.machine_id || '—'),
    el('div', { class: 'field', style: 'margin-top:12px' }, el('label', {}, 'Mã kích hoạt'), keyIn));
  modal('🔑 Bản quyền', body, [
    { label: 'Đóng', onClick: (c) => c() },
    { label: 'Kích hoạt', class: 'primary', onClick: async (c) => { if (!keyIn.value.trim()) return toast('Dán mã kích hoạt'); try { await api('/license/activate', { method: 'POST', body: { key: keyIn.value.trim() } }); c(); toast('Kích hoạt thành công!'); setTimeout(() => location.reload(), 800); } catch (e) { toast(e.message); } } },
  ]);
}
function renderActivation() {
  $('#login').classList.add('hidden'); $('#app').classList.add('hidden');
  const old = document.getElementById('activationRoot'); if (old) old.remove();
  const L = S.license || {};
  const keyIn = el('textarea', { rows: '3', placeholder: 'Dán MÃ KÍCH HOẠT vào đây', style: 'width:100%;padding:10px;border:1px solid var(--line2);border-radius:8px;font-size:13px;box-sizing:border-box;font-family:monospace' });
  const card = el('div', { class: 'login-card', style: 'max-width:460px' },
    el('div', { class: 'login-logo' }, '🔑'),
    el('h1', {}, 'Kích hoạt bản quyền'),
    el('p', { class: 'sub' }, (S.pub && S.pub.restaurant_name || 'QLNH') + ' — đã hết thời gian dùng thử'),
    el('div', { style: 'font-size:13px;color:var(--muted);margin-bottom:4px' }, 'Gửi MÃ MÁY này cho nhà cung cấp để lấy mã kích hoạt:'),
    el('div', { style: 'font-size:20px;font-weight:700;letter-spacing:1px;background:#f1f2f4;border-radius:8px;padding:12px;text-align:center;user-select:all;cursor:copy', title: 'Bấm để copy', onclick: () => { try { navigator.clipboard.writeText(L.machine_id || ''); toast('Đã copy mã máy'); } catch (e) {} } }, L.machine_id || '—'),
    el('div', { class: 'field', style: 'margin-top:14px' }, el('label', {}, 'Mã kích hoạt'), keyIn),
    el('button', { class: 'primary', style: 'width:100%', onclick: async () => { if (!keyIn.value.trim()) return toast('Dán mã kích hoạt'); try { await api('/license/activate', { method: 'POST', body: { key: keyIn.value.trim() } }); toast('Kích hoạt thành công!'); setTimeout(() => location.reload(), 800); } catch (e) { toast(e.message); } } }, 'Kích hoạt'));
  const root = el('div', { id: 'activationRoot', style: 'min-height:100vh;display:flex;align-items:center;justify-content:center;padding:20px' }, card);
  document.body.append(root);
}
/* ====================== Khởi động ====================== */
(async function init() {
  await loadPub();
  try { S.license = await api('/license/status'); } catch (e) { S.license = { blocked: false }; }
  if (S.license && S.license.blocked) { renderActivation(); return; }
  try { localStorage.removeItem('qlnh_login'); } catch (e) {}
  // Khoi phuc phien neu dang dang nhap (vd sau khi luu cai dat -> trang tu reload). KHONG tu dang nhap bang tai khoan mac dinh.
  try { S.user = await api('/me'); enterApp(); return; } catch (e) {}
})();

