:root{
  --bg:#f4f5f7; --surface:#fff; --line:#e3e6ea; --line2:#cfd4da;
  --text:#1c2024; --muted:#6b7280; --accent:#2563eb; --accent-d:#1d4ed8;
  --green-bg:#e7f6ee; --green:#0f7a45; --amber-bg:#fef3da; --amber:#9a6700;
  --red-bg:#fdecec; --red:#c0392b; --radius:10px;
}
*{box-sizing:border-box}
html,body{margin:0;height:100%}
body{font-family:system-ui,'Segoe UI',Roboto,Arial,sans-serif;background:var(--bg);color:var(--text);font-size:15px}
button{font-family:inherit;font-size:14px;cursor:pointer;border:1px solid var(--line2);background:#fff;border-radius:8px;padding:8px 14px;color:var(--text)}
button:hover{background:#f3f4f6}
button.primary{background:var(--accent);border-color:var(--accent);color:#fff}
button.primary:hover{background:var(--accent-d)}
button.danger{background:#fff;border-color:#e2b6b1;color:var(--red)}
button.danger:hover{background:var(--red-bg)}
button.ghost{border-color:transparent;background:transparent}
button:disabled{opacity:.5;cursor:not-allowed}
input,select{font-family:inherit;font-size:14px;padding:8px 10px;border:1px solid var(--line2);border-radius:8px;width:100%;background:#fff;color:var(--text)}
label{font-size:13px;color:var(--muted);display:block;margin-bottom:4px}
.hidden{display:none!important}
.row{display:flex;gap:10px}
.grow{flex:1}
.muted{color:var(--muted)}
.right{text-align:right}
.center{text-align:center}

/* Login */
#login{min-height:100vh;display:flex;align-items:center;justify-content:center;padding:20px}
.login-card{width:340px;background:var(--surface);border:1px solid var(--line);border-radius:16px;padding:28px 24px;box-shadow:0 8px 30px rgba(0,0,0,.06)}
.login-logo{width:54px;height:54px;border-radius:14px;background:#e6efff;color:var(--accent);display:flex;align-items:center;justify-content:center;font-size:28px;margin:0 auto 12px}
.login-card h1{font-size:19px;text-align:center;margin:0 0 2px}
.login-card .sub{text-align:center;color:var(--muted);font-size:13px;margin:0 0 18px}
.field{margin-bottom:12px}
.err{color:var(--red);font-size:13px;min-height:18px;margin:2px 0}

/* App shell */
#app{display:flex;flex-direction:column;height:100vh;overflow:hidden}
.topbar{display:flex;align-items:center;gap:10px;background:var(--surface);border-bottom:1px solid var(--line);padding:9px 16px;position:sticky;top:0;z-index:20;flex-wrap:nowrap}
.brand{font-weight:600;display:flex;align-items:center;gap:8px}
.brand .dot{width:26px;height:26px;border-radius:7px;background:#e6efff;color:var(--accent);display:flex;align-items:center;justify-content:center}
.tabs{display:flex;gap:3px;flex:1;justify-content:center;flex-wrap:nowrap;overflow-x:auto}
.tab{padding:7px 10px;border-radius:8px;font-size:13.5px;cursor:pointer;color:var(--muted);white-space:nowrap}
.tab:hover{background:#f1f2f4}
.tab.active{background:#e6efff;color:var(--accent-d);font-weight:500}
.spacer{flex:0}
.who{font-size:13px;color:var(--muted)}
.content{padding:16px;width:100%;box-sizing:border-box;flex:1;overflow:auto;min-height:0}

/* Tables grid */
.legend{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px;font-size:12px}
.pill{padding:4px 10px;border-radius:20px}
.pill.green{background:var(--green-bg);color:var(--green)}
.pill.amber{background:var(--amber-bg);color:var(--amber)}
.table-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:16px}
.table-card{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:26px 14px;min-height:104px;display:flex;flex-direction:column;justify-content:center;text-align:center;cursor:pointer;transition:.1s}
.table-card:hover{border-color:var(--accent);transform:translateY(-1px)}
.table-card.busy{background:var(--amber-bg);border-color:#f0d9a8}
.table-card .tn{font-weight:600;font-size:19px}
.table-card .ts{font-size:15px;margin-top:6px;color:var(--muted)}
.table-card.busy .ts{color:var(--amber)}

/* Order screen */
.order-wrap{display:grid;grid-template-columns:1fr 420px;gap:14px}
.panel{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);padding:12px}
.cats{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px}
.cat{padding:6px 12px;border-radius:20px;font-size:13px;background:#f1f2f4;cursor:pointer}
.cat.active{background:var(--accent);color:#fff}
.menu-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;max-height:66vh;overflow:auto;padding-right:4px}
.menu-search{width:100%;padding:9px 12px;border:1px solid var(--line2);border-radius:8px;font-size:14px;margin-bottom:10px;box-sizing:border-box}
.menu-item{display:flex;flex-direction:column;justify-content:space-between;gap:6px;min-height:62px;border:1px solid var(--line);border-radius:10px;padding:10px 12px;cursor:pointer;background:#fff}
.menu-item:hover{border-color:var(--accent);background:#f8fbff}
