'use strict';
const express = require('express');
const path = require('path');
const os = require('os');
const crypto = require('crypto');
const { db, getSetting, setSetting, audit, DATA_DIR } = require('./db');
const { hashPassword, verifyPassword, signToken, verifyToken, parseCookies } = require('./auth');
const seed = require('./seed');
const backup = require('./backup');
const license = require('./license');

seed();

const app = express();
app.use(express.json({ limit: '4mb' }));

const PORT = process.env.PORT || 4000;
const REMOTE = (() => { try { return require('./remote'); } catch (e) { return null; } })();
const LOG = (() => { try { return require('./logger'); } catch (e) { const noop = () => {}; return { log: noop, info: noop, warn: noop, error: noop, mask: (x) => '', flush: async () => ({ ok: false }), start: noop, setVersion: noop, listFiles: () => [], readFile: () => [], queueSize: () => 0, machineId: () => '' }; } })();
const ROLE = process.env.QLNH_ROLE || 'central';   // central | local
const APP_VERSION = process.env.QLNH_APP_VERSION || '';   // lay tu app.getVersion() ben Electron main.js, hien cho khach thay dang o ban nao
const { parseCandidates, makeResolver } = require('./endpoint');
if (REMOTE) REMOTE.setLogger((lv, ev, d) => { try { LOG.log(lv, ev, d); } catch (e) {} });
LOG.setVersion(APP_VERSION);

/* ===== COANG BAO VE TRUY CAP TU XA =====
   Chi ap dung cho request di VAO qua duong ham cong khai (host *.trycloudflare.com).
   May trong quan (localhost / LAN) KHONG bi anh huong chut nao.
   Phai nhap dung MA KY THUAT moi di tiep duoc toi man hinh dang nhap. */
const REMOTE_GATE_COOKIE = 'rgate';
function gatePage(msg) {
  return '<!DOCTYPE html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">' +
    '<title>Hỗ trợ từ xa</title><style>body{font-family:system-ui,Arial;max-width:380px;margin:60px auto;padding:0 16px;color:#111}' +
    'h2{font-size:19px}input,button{font-size:17px;padding:12px;width:100%;box-sizing:border-box;margin:6px 0;border:1px solid #ccc;border-radius:10px}' +
    'button{background:#2563eb;color:#fff;border:none;font-weight:600}.m{color:#c0392b;font-weight:600;font-size:14px}' +
    '.q{color:#666;font-size:13px;line-height:1.5}</style></head><body><h2>🔒 Hỗ trợ từ xa</h2>' +
    (msg ? '<p class="m">' + String(msg).replace(/</g, '&lt;') + '</p>' : '') +
    '<p class="q">Nhập MÃ KỸ THUẬT mà chủ quán vừa gửi cho bạn.</p>' +
    '<form method="POST" action="/__cong"><input name="code" inputmode="numeric" autocomplete="off" placeholder="Mã 6 số" autofocus required>' +
    '<button type="submit">Vào</button></form></body></html>';
}
let _gateFails = 0, _gateBlockUntil = 0;
app.use(express.urlencoded({ extended: false, limit: '64kb' }));
app.use((req, res, next) => {
  if (!REMOTE || !REMOTE.isRemoteReq(req)) return next();          // truy cap trong quan -> bo qua hoan toan
  if (!REMOTE.running) return res.status(503).send(gatePage('Cổng hỗ trợ từ xa đang đóng. Nhờ chủ quán bật lại trong Cài đặt.'));
  if (req.method === 'POST' && req.path === '/__cong') {
    if (Date.now() < _gateBlockUntil) return res.status(429).send(gatePage('Sai mã nhiều lần. Thử lại sau 1 phút.'));
    const code = String((req.body && req.body.code) || '').trim();
    const good = REMOTE.code && code.length === REMOTE.code.length &&
      crypto.timingSafeEqual(Buffer.from(code), Buffer.from(REMOTE.code));
    if (!good) {
      _gateFails++;
      if (_gateFails >= 5) { _gateBlockUntil = Date.now() + 60000; _gateFails = 0; LOG.warn('remote.gate.block', 'Chan tam 1 phut do nhap sai ma ky thuat nhieu lan'); }
      LOG.warn('remote.gate.fail', 'Nhap SAI ma ky thuat tu ' + (req.headers['cf-connecting-ip'] || '?'));
      return res.status(401).send(gatePage('Sai mã. Kiểm tra lại mã chủ quán gửi.'));
    }
    _gateFails = 0;
    res.setHeader('Set-Cookie', REMOTE_GATE_COOKIE + '=' + signToken({ g: 'remote' }, 12 * 3600 * 1000) + '; Path=/; HttpOnly; Secure; SameSite=Lax');
    LOG.warn('remote.gate.ok', 'Ky thuat da qua cong tu xa (IP ' + (req.headers['cf-connecting-ip'] || '?') + ')');
    return res.redirect('/');
  }
  const tk = verifyToken(parseCookies(req)[REMOTE_GATE_COOKIE]);
  if (tk && tk.g === 'remote') return next();
  if (req.path.startsWith('/api/')) return res.status(401).json({ error: 'Chua qua cong ho tro tu xa' });
  return res.status(401).send(gatePage(''));
});
const CENTRAL_CANDIDATES = parseCandidates(process.env.QLNH_CENTRAL_URLS || process.env.QLNH_CENTRAL_URL);
const SYNC_KEY_ENV = process.env.QLNH_SYNC_KEY || '';
const WRITE_THROUGH = ROLE === 'local' && CENTRAL_CANDIDATES.length > 0 && !!SYNC_KEY_ENV;
const centralResolver = WRITE_THROUGH ? makeResolver(CENTRAL_CANDIDATES) : null;
const RANK = { staff: 1, admin: 2, owner: 3 };
// Phan quyen chi tiet: chu quan (owner) luon co toan quyen; nguoi khac theo danh sach perms
const ALL_PERMS = ['stats', 'menu', 'debts', 'approve', 'users', 'settings', 'delbill'];
function permsOf(row) { if (!row) return []; if (row.role === 'owner') return ALL_PERMS.slice(); try { const p = JSON.parse(row.perms || '[]'); return Array.isArray(p) ? p : []; } catch (e) { return []; } }
function canDo(row, key) { return !!row && (row.role === 'owner' || permsOf(row).includes(key)); }
// ====== TU DONG DANG NHAP (chi may dev) ======
// Bat bang 1 trong 2 cach (ban giao khach KHONG lam -> van phai dang nhap):
//   - Bien moi truong:  QLNH_AUTOLOGIN=chuquan
//   - Hoac tao file 'autologin.txt' (noi dung = ten dang nhap) trong thu muc du lieu cua app.
let AUTOLOGIN_NAME = (process.env.QLNH_AUTOLOGIN || '').trim();
if (!AUTOLOGIN_NAME) { try { const _fs = require('fs'); const _p = path.join(DATA_DIR, 'autologin.txt'); if (_fs.existsSync(_p)) AUTOLOGIN_NAME = _fs.readFileSync(_p, 'utf8').trim(); } catch (e) {} }
if (AUTOLOGIN_NAME) console.log('[QLNH] Tu dong dang nhap voi tai khoan:', AUTOLOGIN_NAME);
function tokenOrAuto(req) {
  let u = verifyToken(parseCookies(req).token);
  if (!u && AUTOLOGIN_NAME) { const r = db.prepare('SELECT id FROM users WHERE username=? AND active=1').get(AUTOLOGIN_NAME); if (r) u = { id: r.id }; }
  return u;
}
function authPerm(key) {
  return (req, res, next) => {
    const u = tokenOrAuto(req);
    if (!u) return res.status(401).json({ error: 'Chua dang nhap' });
    const row = db.prepare('SELECT id,username,name,role,active,perms FROM users WHERE id=?').get(u.id);
    if (!row || !row.active) return res.status(401).json({ error: 'Tai khoan khong hop le' });
    req.user = row;
    if (!canDo(row, key)) return res.status(403).json({ error: 'Khong du quyen' });
    next();
  };
}
function money(n) { return Math.round(Number(n) || 0); }
function qtyNum(n) { const x = Number(n); return isFinite(x) && x > 0 ? Math.round(x * 1000) / 1000 : 0; } // so luong cho phep so le (vd 2.2 Kg)
// Moc thoi gian dung cho updated_at/dong bo: tren MAY QUAY duoc cong do lech dong ho so voi may chu
// (sync-agent luu setting clock_skew_ms) -> so sanh "ban nao moi hon" giua 2 may moi dung.
let _skewCache = { v: 0, at: 0 };
function clockSkewMs() {
  if (ROLE !== 'local') return 0;
  const t = Date.now();
  if (t - _skewCache.at > 10000) { _skewCache = { v: Number(getSetting('clock_skew_ms') || 0) || 0, at: t }; }
  return _skewCache.v;
}
function nowStr() { return new Date(Date.now() + clockSkewMs()).toISOString().replace('T', ' ').slice(0, 23); }
function localNowStr() { const d = new Date(); const p = (n) => String(n).padStart(2, '0'); return d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate()) + ' ' + p(d.getHours()) + ':' + p(d.getMinutes()) + ':' + p(d.getSeconds()); }
// Chuan hoa chuoi ngay gio "YYYY-MM-DD HH:MM[:SS]" (nhan ca dang co chu T)
function normDateTime(v) {
  let dt = String(v == null ? '' : v).trim().replace('T', ' ');
  if (!dt) return '';
  if (/^\d{4}-\d{2}-\d{2}$/.test(dt)) dt += ' 00:00:00';
  if (/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$/.test(dt)) dt += ':00';
  return /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(dt) ? dt : '';
}

/* ===== CONG NO: cac lan thu (bang debt_payments) =====
   orders.debt_amount = so no GOC luc thanh toan bill (khong doi).
   Con no = debt_amount - tong da thu (cac dong debt_payments chua huy).
   Tien thu no tinh vao NGAY THU (debt_payments.paid_at), khong phai ngay ban.
   Cac cot debt_settled/debt_settled_at/debt_paid_cash/debt_paid_transfer duoc TINH LAI
   tu bang nay (giu lai de tuong thich ban cu + dong bo). */
const listDebtPayments = (orderUuid) => (orderUuid ? db.prepare('SELECT * FROM debt_payments WHERE order_uuid=? ORDER BY paid_at, id').all(orderUuid) : []);
function debtPaidOf(orderUuid) {
  let cash = 0, transfer = 0, last = null;
  for (const r of listDebtPayments(orderUuid)) {
    if (r.voided) continue;
    cash += money(r.cash); transfer += money(r.transfer);
    if (!last || String(r.paid_at) > last) last = String(r.paid_at);
  }
  return { cash, transfer, total: cash + transfer, last_at: last };
}
// Tinh lai 4 cot tom tat tren orders tu bang debt_payments
function recalcDebt(orderId) {
  const o = db.prepare('SELECT id,uuid,debt_amount FROM orders WHERE id=?').get(orderId);
  if (!o) return null;
  const p = debtPaidOf(o.uuid);
  const debt = money(o.debt_amount);
  const remaining = Math.max(0, debt - p.total);
  const settled = (debt > 0 && remaining <= 0) ? 1 : (debt > 0 ? 0 : 1);
  db.prepare('UPDATE orders SET debt_settled=?, debt_settled_at=?, debt_paid_cash=?, debt_paid_transfer=? WHERE id=?')
    .run(settled, (settled && p.last_at ? p.last_at : (p.last_at || null)), p.cash, p.transfer, o.id);
  return { debt, paid: p.total, remaining, settled };
}
// Gop cac lan thu no nhan tu may kia theo uuid (KHONG xoa dong cu -> khong bao gio mat tien thu no,
// ke ca khi 2 may lech dong ho lam ban ghi don bi tu choi theo last-write-wins).
function mergeDebtPayments(orderUuid, payments) {
  if (!orderUuid || !Array.isArray(payments)) return 0;
  let n = 0;
  for (const dp of payments) {
    if (!dp || !dp.uuid) continue;
    const ex = db.prepare('SELECT id, updated_at FROM debt_payments WHERE uuid=?').get(dp.uuid);
    const ts = dp.updated_at || nowStr();
    if (ex) {
      if (ex.updated_at && ts <= ex.updated_at) continue; // da co ban moi hon
      db.prepare('UPDATE debt_payments SET order_uuid=?,paid_at=?,cash=?,transfer=?,staff_name=?,note=?,voided=?,updated_at=? WHERE uuid=?')
        .run(orderUuid, String(dp.paid_at || ''), money(dp.cash), money(dp.transfer), dp.staff_name || null, dp.note || '', dp.voided ? 1 : 0, ts, dp.uuid);
    } else {
      db.prepare('INSERT INTO debt_payments(uuid,order_uuid,paid_at,cash,transfer,staff_name,note,voided,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)')
        .run(dp.uuid, orderUuid, String(dp.paid_at || ''), money(dp.cash), money(dp.transfer), dp.staff_name || null, dp.note || '', dp.voided ? 1 : 0, dp.created_at || nowStr(), ts);
    }
    n++;
  }
  return n;
}

let dataVersion = 1;
let _dirtySinceSnap = false;
function touch() { dataVersion++; _dirtySinceSnap = true; }
// Chu ky trang thai DB: doi khi don/mon thay doi ke ca do sync-agent (tien trinh khac) ghi vao -> UI tu lam moi
function dbSig() {
  try {
    const o = db.prepare("SELECT COUNT(*) c, COALESCE(MAX(updated_at),'') m FROM orders").get();
    const oi = db.prepare('SELECT COALESCE(MAX(id),0) x, COUNT(*) c FROM order_items').get();
    const tb = db.prepare('SELECT COALESCE(MAX(id),0) x, COUNT(*) c FROM tables').get();
    return o.c + '.' + o.m + '.' + oi.x + '.' + oi.c + '.' + tb.x + '.' + tb.c;
  } catch (e) { return ''; }
}

// Ghi thang len may chu ngay sau moi thao tac (best-effort). Offline -> agent bu sau.
function pushOrderToCentral(orderId) {
  if (!WRITE_THROUGH) return;
  let o, stamp;
  try {
    o = db.prepare('SELECT * FROM orders WHERE id=?').get(orderId);
    if (!o) return;
    stamp = o.updated_at;
    o.items = db.prepare('SELECT name,price,qty,note,sent,del_req,tax FROM order_items WHERE order_id=?').all(orderId);
    o.debt_payments_all = db.prepare('SELECT uuid,paid_at,cash,transfer,staff_name,note,voided,created_at,updated_at FROM debt_payments WHERE order_uuid=?').all(o.uuid || '');
  } catch (e) { return; }
  centralResolver.resolve().then(url => {
    if (!url) return;
    fetch(url + '/api/sync/orders', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-sync-key': SYNC_KEY_ENV },
      body: JSON.stringify({ orders: [o] }),
      signal: AbortSignal.timeout(5000),
    }).then(r => (r.ok ? r.json() : null)).then(r => {
      // CHI danh dau da dong bo khi may chu XAC NHAN da nhan don nay. Truoc day danh dau bua -> don bi
      // may chu tu choi (lech dong ho) se khong bao gio duoc gui lai => 2 may lech vinh vien.
      const rejReason = (r && Array.isArray(r.rejected) ? (r.rejected.find(x => x && x.uuid === o.uuid) || null) : null);
      // 'older'/'void' = may chu da co ban moi hon (hoac bill da xoa) -> NHUONG may chu, khong day lai mai.
      // An toan vi cac lan THU NO da duoc gop rieng theo uuid o tren, khong phu thuoc last-write-wins.
      const deferred = rejReason && (rejReason.reason === 'older' || rejReason.reason === 'void');
      const okThis = r && r.ok && (!Array.isArray(r.accepted) || r.accepted.indexOf(o.uuid) >= 0 || deferred);
      if (okThis) { try { db.prepare('UPDATE orders SET synced=1 WHERE id=? AND updated_at=?').run(orderId, stamp); } catch (e) {} }
    }).catch(() => { centralResolver.invalidate(); });
  });
}
function pushMenuToCentral() {
  if (!WRITE_THROUGH) return;
  let payload;
  try {
    const categories = db.prepare('SELECT uuid,name,sort,active FROM categories').all();
    const items = db.prepare('SELECT i.uuid, i.name, i.price, i.active, i.sort, i.image, c.uuid AS category_uuid FROM items i LEFT JOIN categories c ON c.id=i.category_id').all();
    payload = { categories, items };
  } catch (e) { return; }
  centralResolver.resolve().then(url => { if (!url) return; fetch(url + '/api/sync/menu', { method: 'POST', headers: { 'Content-Type': 'application/json', 'x-sync-key': SYNC_KEY_ENV }, body: JSON.stringify(payload), signal: AbortSignal.timeout(8000) }).catch(() => { centralResolver.invalidate(); }); });
}
function markUnsynced(orderId) {
  db.prepare('UPDATE orders SET synced=0, updated_at=? WHERE id=?').run(nowStr(), orderId);
  touch();
  pushOrderToCentral(orderId);
}

