function tableWithOrder() {
  // Gop: moi ban chi giu 1 don mo moi nhat, huy cac don mo trung (tu chua lanh)
  const opens = db.prepare("SELECT id, table_id, COALESCE(updated_at,created_at,'') ua FROM orders WHERE status='open' AND table_id IS NOT NULL AND cancel_req=0").all();
  const best = {};
  for (const o of opens) if (!best[o.table_id] || o.ua > best[o.table_id].ua) best[o.table_id] = o;
  for (const o of opens) { const b = best[o.table_id]; if (b && o.id !== b.id) db.prepare("UPDATE orders SET status='void' WHERE id=?").run(o.id); }
  // Huy don "mo coi" (dang mo nhung khong gan ban nao) -> tranh dem sai "dang phuc vu"
  db.prepare("UPDATE orders SET status='void' WHERE status='open' AND table_id IS NULL").run();
  const tables = db.prepare('SELECT * FROM tables ORDER BY sort,id').all();
  const openOrders = db.prepare("SELECT * FROM orders WHERE status='open'").all();
  const byTable = {};
  for (const o of openOrders) {
    if (o.cancel_req) continue; // ban dang xin huy ca ban -> coi nhu trong, cho khach moi ngoi
    const total = db.prepare('SELECT COALESCE(SUM(price*qty),0) t FROM order_items WHERE order_id=?').get(o.id).t;
    if (total > 0) {
      byTable[o.table_id] = { order_id: o.id, total, code: o.code, cancel_req: o.cancel_req || 0 };
      for (const ex of parseExtra(o.extra_tables)) byTable[ex] = { order_id: o.id, total, code: o.code, cancel_req: o.cancel_req || 0, merged: true };
    }
  }
  return tables.map(t => Object.assign({}, t, { open: byTable[t.id] || null }));
}
