// ---------- Orders ----------
function orderCode() { const n = Number(getSetting('order_seq') || 0) + 1; setSetting('order_seq', String(n)); return 'HD' + String(n).padStart(5, '0'); }
// Tinh thue VAT theo tung suat (bia/ruou 10%, mon an 8%...): gom mon theo suat, (tien - KM theo ty le) * suat, roi cong
function computeTax(items, dpct, applyTax) {
  if (!applyTax) return { tax_amount: 0, breakdown: [] };
  const groups = {};
  for (const i of items) {
    if (i.del_req) continue;
    const r = Number(i.tax || 0);
    if (r > 0) groups[r] = (groups[r] || 0) + i.price * i.qty;
  }
  let tax_amount = 0; const breakdown = [];
  Object.keys(groups).map(Number).sort((a, b) => a - b).forEach(r => {
    const gsub = groups[r];
    const gAfter = Math.max(0, gsub - Math.round(gsub * (dpct || 0) / 100));
    const t = Math.round(gAfter * r / 100);
    if (t > 0) { breakdown.push({ rate: r, amount: t }); tax_amount += t; }
  });
  return { tax_amount, breakdown };
}
function getOrderFull(id) {
  const order = db.prepare('SELECT * FROM orders WHERE id=?').get(id);
  if (!order) return null;
  order.items = db.prepare('SELECT * FROM order_items WHERE order_id=? ORDER BY id').all(id);
  order.items.forEach(i => {
    if ((!i.tax || Number(i.tax) === 0) && i.item_id) {
      const it = db.prepare('SELECT tax FROM items WHERE id=?').get(i.item_id);
      if (it && Number(it.tax) > 0) { i.tax = Number(it.tax); try { db.prepare('UPDATE order_items SET tax=? WHERE id=?').run(i.tax, i.id); } catch (e) {} }
    }
  });
  order.subtotal = order.items.reduce((s, i) => s + (i.del_req ? 0 : i.price * i.qty), 0);
  const dpct = order.discount_pct || 0;
  order.discount_pct = dpct;
  order.discount_amount = Math.round(order.subtotal * dpct / 100);
  const afterDisc = Math.max(0, order.subtotal - order.discount_amount);
  const tx = computeTax(order.items, dpct, order.apply_tax);
  order.tax_amount = tx.tax_amount;
  order.tax_breakdown = tx.breakdown;
  order.tax_pct = null;
  order.total = afterDisc + order.tax_amount;
  order.deposit = Number(order.deposit || 0);
  order.payable = Math.max(0, order.total - order.deposit);
  order.paid_cash = Number(order.paid_cash || 0);
  order.paid_transfer = Number(order.paid_transfer || 0);
  order.debt_amount = Number(order.debt_amount || 0);
  if (order.status === 'paid' && !order.paid_cash && !order.paid_transfer && !order.debt_amount) {
    const _pm = order.payment_method || 'cash';
    if (_pm === 'debt') order.debt_amount = order.payable; else if (_pm === 'transfer') order.paid_transfer = order.payable; else order.paid_cash = order.payable;
  }
  order.has_pending = order.items.some(i => i.del_req);
  // Cong no: cac lan thu + con no
  const _dp = debtPaidOf(order.uuid);
  order.debt_paid_cash_total = _dp.cash;
  order.debt_paid_transfer_total = _dp.transfer;
  order.debt_paid_total = _dp.total;
  order.debt_remaining = Math.max(0, order.debt_amount - _dp.total);
  order.debt_payments = listDebtPayments(order.uuid).filter(r => !r.voided);
  return order;
}
function parseExtra(v) { return String(v || '').split(',').map((x) => Number(x)).filter(Boolean); }
function tableIdsOfOrder(o) { return [o.table_id].concat(parseExtra(o.extra_tables)).filter(Boolean); }
function namesForIds(ids) { return ids.map((id) => { const t = db.prepare('SELECT name FROM tables WHERE id=?').get(id); return t ? t.name : ''; }).filter(Boolean).join(' + '); }
function openOrderForTable(tableId, user) {
  let o = db.prepare("SELECT * FROM orders WHERE status='open' AND cancel_req=0 AND (table_id=? OR (',' || COALESCE(extra_tables,'') || ',') LIKE '%,' || ? || ',%')").get(tableId, String(tableId));
  if (!o) {
    const t = db.prepare('SELECT name FROM tables WHERE id=?').get(tableId);
    const id = db.prepare('INSERT INTO orders(code,uuid,table_id,table_names,created_by,staff_name,updated_at,synced) VALUES(?,?,?,?,?,?,?,0)')
      .run(orderCode(), crypto.randomUUID(), tableId, t ? t.name : '', user.id, user.name, nowStr()).lastInsertRowid;
    o = db.prepare('SELECT * FROM orders WHERE id=?').get(id);
    touch();
  }
  return o;
}
