app.post('/api/orders/:id/merge', authRequired(), (req, res) => {
  const dest = db.prepare("SELECT * FROM orders WHERE id=? AND status='open'").get(req.params.id);
  if (!dest) return res.status(400).json({ error: 'Don khong mo' });
  const targetTableId = req.body.table_id != null ? Number(req.body.table_id) : null;
  let src = null;
  if (req.body.from_order_id) src = db.prepare("SELECT * FROM orders WHERE id=? AND status='open'").get(req.body.from_order_id);
  else if (targetTableId) src = db.prepare("SELECT * FROM orders WHERE status='open' AND cancel_req=0 AND (table_id=? OR (',' || COALESCE(extra_tables,'') || ',') LIKE '%,' || ? || ',%')").get(targetTableId, String(targetTableId));
  if (src && src.id === dest.id) return res.status(400).json({ error: 'Ban da thuoc don nay' });

  let ids = tableIdsOfOrder(dest);
  if (src) {
    db.prepare('UPDATE order_items SET order_id=? WHERE order_id=?').run(dest.id, src.id);
    ids = ids.concat(tableIdsOfOrder(src));
    db.prepare("UPDATE orders SET status='void', note='Gop vao '||?, extra_tables='' WHERE id=?").run(dest.code, src.id);
  } else if (targetTableId) {
    if (!db.prepare('SELECT 1 FROM tables WHERE id=?').get(targetTableId)) return res.status(400).json({ error: 'Ban khong ton tai' });
    ids.push(targetTableId);
  } else { return res.status(400).json({ error: 'Chua chon ban' }); }

  const primary = dest.table_id;
  const extras = [...new Set(ids)].filter((id) => id && id !== primary);
  db.prepare('UPDATE orders SET extra_tables=?, table_names=? WHERE id=?').run(extras.join(','), namesForIds([primary].concat(extras)), dest.id);
  audit(req.user, 'order.merge', dest.code + ' + ban ' + (targetTableId || (src ? src.table_id : '?')));
  markUnsynced(dest.id); if (src) markUnsynced(src.id);
  res.json(getOrderFull(dest.id));
});
