app.post('/api/orders/:id/pay', authRequired(), (req, res) => {
  const b = req.body || {};
  const o = getOrderFull(Number(req.params.id));
  if (!o || o.status !== 'open') return res.status(400).json({ error: 'Don khong mo' });
  if (!o.items.filter(i => !i.del_req).length) return res.status(400).json({ error: 'Don khong co mon de tinh tien' });
  const total = (o.payable != null ? o.payable : o.total);
  let cash, transfer;
  if (b.paid_cash != null || b.paid_transfer != null) { cash = Math.max(0, money(b.paid_cash) || 0); transfer = Math.max(0, money(b.paid_transfer) || 0); }
  else { const pm0 = b.payment_method || 'cash'; if (pm0 === 'transfer') { cash = 0; transfer = total; } else if (pm0 === 'debt') { cash = 0; transfer = 0; } else { cash = total; transfer = 0; } }
  if (cash + transfer > total) { if (transfer >= total) { transfer = total; cash = 0; } else cash = total - transfer; }
  const debt = Math.max(0, total - cash - transfer);
  if (debt > 0 && !String(b.customer_name || '').trim()) return res.status(400).json({ error: 'Con no -> can nhap ten khach' });
  const pm = (debt > 0) ? ((cash || transfer) ? 'partial' : 'debt') : ((cash && transfer) ? 'mixed' : (transfer ? 'transfer' : 'cash'));
  const settled = debt > 0 ? 0 : 1;
  db.prepare("UPDATE orders SET status='paid',tax_pct=NULL,payment_method=?,paid_cash=?,paid_transfer=?,debt_amount=?,customer_name=?,customer_phone=?,customer_note=?,debt_settled=?,paid_at=COALESCE(biz_at,datetime('now','localtime')) WHERE id=?")
    .run(pm, cash, transfer, debt, (debt > 0 ? String(b.customer_name || '') : (b.customer_name ? String(b.customer_name) : null)), (debt > 0 ? String(b.customer_phone || '') : null), (debt > 0 ? String(b.customer_note || '') : null), settled, o.id);
  recalcDebt(o.id); // dong bo lai debt_settled theo cac lan thu (bill moi thi chua co lan nao)
  const full = getOrderFull(o.id);
  audit(req.user, 'order.pay', o.code + ' TM=' + cash + ' CK=' + transfer + ' No=' + debt);
  LOG.info('order.pay', o.code + ' tong=' + full.total + ' coc=' + full.deposit + ' phaitra=' + total + ' TM=' + cash + ' CK=' + transfer + ' no=' + debt,
    { uuid: o.uuid, by: req.user.username, pm, paid_at: full.paid_at, biz_at: full.biz_at, khach: debt > 0 ? LOG.mask(b.customer_name) : '' });
  markUnsynced(o.id); res.json(full);
});
