// Ngay/gio don: 'Len don bu' (chi ngay gio) hoac 'Dat ban' (ngay gio + ten/SDT + tien coc). Doanh thu tinh theo gio nay.
app.post('/api/orders/:id/datetime', authRequired(), (req, res) => {
  const o = db.prepare("SELECT * FROM orders WHERE id=? AND status='open'").get(req.params.id);
  if (!o) return res.status(400).json({ error: 'Don khong mo' });
  const b = req.body || {};
  if (b.clear) {
    db.prepare("UPDATE orders SET biz_at=NULL, created_at=datetime('now','localtime'), deposit=0, deposit_at=NULL, deposit_method=NULL, customer_name=NULL, customer_phone=NULL WHERE id=?").run(o.id);
    audit(req.user, 'order.datetime', o.code + ' -> hien tai');
    markUnsynced(o.id); return res.json(getOrderFull(o.id));
  }
  let dt = b.datetime ? String(b.datetime).trim() : '';
  if (!dt) return res.status(400).json({ error: 'Chua chon ngay gio' });
  dt = dt.replace('T', ' ');
  if (/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$/.test(dt)) dt += ':00';
  if (!/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(dt)) return res.status(400).json({ error: 'Ngay gio khong hop le' });
  if (b.booking) {
    const dep = money(b.deposit) || 0;
    // Tien coc la tien THUC THU luc nhan coc -> ghi ngay + hinh thuc de vao dung dong tien ngay do
    const depAt = dep > 0 ? (normDateTime(b.deposit_at) || o.deposit_at || localNowStr()) : null;
    const depPm = dep > 0 ? (b.deposit_method === 'transfer' ? 'transfer' : 'cash') : null;
    db.prepare('UPDATE orders SET biz_at=?, created_at=?, customer_name=?, customer_phone=?, deposit=?, deposit_at=?, deposit_method=? WHERE id=?')
      .run(dt, dt, (b.customer_name || '').trim() || null, (b.customer_phone || '').trim() || null, dep, depAt, depPm, o.id);
    audit(req.user, 'order.datban', o.code + ' dat ban ' + dt + ' coc ' + dep + (dep > 0 ? (' (' + depPm + ' ' + depAt + ')') : ''));
    LOG.info('order.datban', o.code + ' dat ban ' + dt + ' coc=' + dep + (dep > 0 ? (' thu bang ' + depPm + ' ngay ' + depAt) : ''), { uuid: o.uuid, by: req.user.username });
  } else {
    db.prepare('UPDATE orders SET biz_at=?, created_at=? WHERE id=?').run(dt, dt, o.id);
    audit(req.user, 'order.datetime', o.code + ' -> ' + dt);
    LOG.info('order.datetime', o.code + ' doi ngay gio don -> ' + dt, { uuid: o.uuid, by: req.user.username });
  }
  markUnsynced(o.id); res.json(getOrderFull(o.id));
});
