app.post('/api/orders/:id/settle-debt', authPerm('debts'), (req, res) => {
  const b = req.body || {};
  const o = getOrderFull(Number(req.params.id));
  if (!o || !(Number(o.debt_amount || 0) > 0)) return res.status(404).json({ error: 'Khong tim thay khoan no' });
  if (!o.uuid) return res.status(400).json({ error: 'Don thieu ma dinh danh' });
  const remaining = Math.max(0, Number(o.debt_remaining || 0));
  if (remaining <= 0) return res.status(400).json({ error: 'Khoan no nay da thu du' });
  let cash = Math.max(0, money(b.pay_cash) || 0), transfer = Math.max(0, money(b.pay_transfer) || 0);
  if (cash + transfer <= 0) { cash = remaining; transfer = 0; }             // khong nhap gi -> mac dinh thu du bang tien mat
  if (cash + transfer > remaining) {                                        // thu THUA -> cat bot cho bang so con no
    if (transfer >= remaining) { transfer = remaining; cash = 0; } else cash = remaining - transfer;
  }
  // Thu THIEU van ghi nhan binh thuong -> phan con lai VAN nam trong tab Cong no (tra gop nhieu lan)
  const at = normDateTime(b.paid_at) || localNowStr();
  db.prepare('INSERT INTO debt_payments(uuid,order_uuid,paid_at,cash,transfer,staff_name,note,voided,created_at,updated_at) VALUES(?,?,?,?,?,?,?,0,?,?)')
    .run(crypto.randomUUID(), o.uuid, at, cash, transfer, req.user.name || '', String(b.note || ''), localNowStr(), nowStr());
  const st = recalcDebt(o.id);
  audit(req.user, 'debt.settle', o.code + ' ' + (o.customer_name || '') + ' TM=' + cash + ' CK=' + transfer + ' ngay ' + at + ' con no ' + st.remaining);
  LOG.info('debt.settle', o.code + ' thu TM=' + cash + ' CK=' + transfer + ' vao ngay ' + at + ' | no goc=' + o.debt_amount + ' con lai=' + st.remaining,
    { uuid: o.uuid, by: req.user.username, ngay_an: o.paid_at, khach: LOG.mask(o.customer_name) });
  markUnsynced(o.id); res.json({ ok: true, paid: cash + transfer, remaining: st.remaining, settled: !!st.settled });
});
