  db.prepare("UPDATE orders SET status='void' WHERE id=?").run(o.id);
  audit(req.user, 'order.cancel', o.code + (o.items.length ? ' (' + o.items.length + ' mon)' : ' (rong)'));
  markUnsynced(o.id);
  res.json({ ok: true });
});

// ---------- Stats ----------
function dateOnly(s) { return /^\d{4}-\d{2}-\d{2}$/.test(String(s || '')) ? String(s) : null; }
function rangeClause(q) {
  q = q || {};
  const r = q.range || 'today';
  if (r === 'custom') { const f = dateOnly(q.from), t = dateOnly(q.to); if (f && t) return "date(paid_at) BETWEEN date('" + f + "') AND date('" + t + "')"; }
  if (r === 'yesterday') return "date(paid_at)=date('now','localtime','-1 day')";
  if (r === 'week' || r === '7days') return "date(paid_at) >= date('now','localtime','-6 days')";
  if (r === '30days') return "date(paid_at) >= date('now','localtime','-29 days')";
  if (r === 'month') return "strftime('%Y-%m',paid_at)=strftime('%Y-%m','now','localtime')";
  if (r === 'lastmonth') return "strftime('%Y-%m',paid_at)=strftime('%Y-%m','now','localtime','-1 month')";
  if (r === 'year') return "strftime('%Y',paid_at)=strftime('%Y','now','localtime')";
  return "date(paid_at)=date('now','localtime')";
}
function splitOf(o) {
  let cash = Number(o.paid_cash || 0), transfer = Number(o.paid_transfer || 0), debt = Number(o.debt_amount || 0);
  if (!cash && !transfer && !debt) {
    const payable = Math.max(0, revenueOf(o) - Number(o.deposit || 0));
    const pm = o.payment_method || 'cash';
    if (pm === 'debt') debt = payable; else if (pm === 'transfer') transfer = payable; else cash = payable;
  }
  return { cash, transfer, debt };
}
function revenueOf(o) {
  const items = db.prepare('SELECT price,qty,tax,del_req FROM order_items WHERE order_id=? AND del_req=0').all(o.id);
  const sub = items.reduce((s, i) => s + i.price * i.qty, 0);
  const discAmt = Math.round(sub * (o.discount_pct || 0) / 100);
  const afterDisc = Math.max(0, sub - discAmt);
  return afterDisc + computeTax(items, o.discount_pct || 0, o.apply_tax).tax_amount;
}
app.get('/api/stats/summary', authPerm('stats'), (req, res) => {
  const paid = db.prepare("SELECT * FROM orders WHERE status='paid' AND NOT EXISTS (SELECT 1 FROM order_items pi WHERE pi.order_id=orders.id AND pi.del_req=1) AND " + rangeClause(req.query)).all();
  let revenue = 0, cash_total = 0, transfer_total = 0;
  for (const o of paid) { revenue += revenueOf(o); const sp = splitOf(o); cash_total += sp.cash; transfer_total += sp.transfer; }
  // Tien THU NO trong khoang (theo NGAY THU cua tung lan thu). Chi tinh bill con hieu luc (khong tinh bill da xoa/huy).
  const dpRows = db.prepare("SELECT dp.cash, dp.transfer FROM debt_payments dp JOIN orders o ON o.uuid=dp.order_uuid WHERE dp.voided=0 AND o.status='paid' AND " + rangeClause(req.query).replace(/paid_at/g, 'dp.paid_at')).all();
  let debt_collected = 0;
  for (const sr of dpRows) { cash_total += Number(sr.cash || 0); transfer_total += Number(sr.transfer || 0); debt_collected += Number(sr.cash || 0) + Number(sr.transfer || 0); }
  // Tien COC nhan luc dat ban -> la tien THUC THU ngay nhan coc (bill tra not phan con lai o ngay an)
  const depRows = db.prepare("SELECT deposit, deposit_method FROM orders WHERE COALESCE(deposit,0)>0 AND deposit_at IS NOT NULL AND status IN ('open','paid') AND " + rangeClause(req.query).replace(/paid_at/g, 'deposit_at')).all();
  let deposit_total = 0;
  for (const dr of depRows) { const v = Number(dr.deposit || 0); deposit_total += v; if (dr.deposit_method === 'transfer') transfer_total += v; else cash_total += v; }
  const orders = paid.length;
  const serving = tableWithOrder().filter(t => t.open).length;
  // Cong no dang chua thu (toan bo, khong theo khoang)
  const debtRows = db.prepare("SELECT * FROM orders WHERE status='paid' AND (debt_amount>0 OR payment_method='debt')").all();
  let debt_total = 0, debt_num = 0;
  for (const r of debtRows) { const dv = Math.max(0, splitOf(r).debt - debtPaidOf(r.uuid).total); if (dv > 0) { debt_total += dv; debt_num++; } }
  // Bill co mon dang cho duyet huy (mo hoac da thanh toan)
  const pendIds = db.prepare("SELECT DISTINCT order_id FROM order_items WHERE del_req=1").all().map(r => r.order_id);
  let pending_count = 0, pending_total = 0;
  for (const id of pendIds) { const o = db.prepare("SELECT id FROM orders WHERE id=? AND status IN ('open','paid')").get(id); if (o) { pending_count++; pending_total += getOrderFull(o.id).total; } }
  res.json({ revenue, orders, avg: orders ? Math.round(revenue / orders) : 0, serving, cash_total, transfer_total, debt_total, debt_count: debt_num, debt_collected, deposit_total, pending_count, pending_total });
});
