// ---------- Xuat bao cao Excel (dung exceljs -> file .xlsx that, dinh dang dep) ----------
function vnDate(s) { s = String(s || ''); return s.length >= 10 ? s.slice(8, 10) + '/' + s.slice(5, 7) + '/' + s.slice(0, 4) : s; }
function vnTime(s) { s = String(s || ''); return s.length >= 16 ? s.slice(11, 16) : ''; }
// Tien hang - KM - thue cua 1 don (thue gop theo suat, tong khop doanh thu)
function billOf(o) {
  const items = db.prepare('SELECT oi.*, it.code icode, it.unit iunit FROM order_items oi LEFT JOIN items it ON it.id=oi.item_id WHERE oi.order_id=? AND oi.del_req=0 ORDER BY oi.id').all(o.id);
  const sub = items.reduce((s, i) => s + i.price * i.qty, 0);
  const dpct = o.discount_pct || 0;
  const disc = Math.round(sub * dpct / 100);
  const total = revenueOf(o);
  const tax = Math.max(0, total - (sub - disc));
  return { items, sub, dpct, disc, tax, total };
}
const XLS_BRAND = 'FF2563EB';        // xanh thuong hieu, khop --accent trong style.css
const XLS_BRAND_LT = 'FFEFF4FF';     // xanh nhat cho dong TONG CUOI
const XLS_ROW_ALT = 'FFF7F8FA';      // xen ke nhe cho de doc
const XLS_WARN = 'FFFEF3C7';         // vang nhat - dong tong nhom cong no
const XLS_WARN_NAME = 'FFFFE4C4';    // cam nhat - dong tong nhom GOP THEO TEN (canh bao)
const fmtMoney = '#,##0';
function newReportSheet(wb, opts) {
  const ws = wb.addWorksheet('Bao cao');
  ws.columns = opts.cols;
  ws.mergeCells(1, 1, 1, opts.cols.length); ws.getCell(1, 1).value = opts.rname; ws.getCell(1, 1).font = { bold: true, size: 15, color: { argb: XLS_BRAND } };
  let r = 2;
  if (opts.addr) { ws.mergeCells(r, 1, r, opts.cols.length); ws.getCell(r, 1).value = 'Địa chỉ: ' + opts.addr; ws.getCell(r, 1).font = { size: 10, color: { argb: 'FF6B7280' } }; r++; }
  if (opts.phone) { ws.mergeCells(r, 1, r, opts.cols.length); ws.getCell(r, 1).value = 'SĐT: ' + opts.phone; ws.getCell(r, 1).font = { size: 10, color: { argb: 'FF6B7280' } }; r++; }
  ws.mergeCells(r, 1, r, opts.cols.length); ws.getCell(r, 1).value = opts.title; ws.getCell(r, 1).font = { bold: true, size: 12 }; r++;
  ws.mergeCells(r, 1, r, opts.cols.length); ws.getCell(r, 1).value = opts.label; ws.getCell(r, 1).font = { size: 10, italic: true, color: { argb: 'FF6B7280' } }; r++;
  r++; // dong trong
  const hr = ws.getRow(r);
  opts.cols.forEach((c, i) => { hr.getCell(i + 1).value = c.header; });
  hr.eachCell((cell) => { cell.font = { bold: true, color: { argb: 'FFFFFFFF' } }; cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: XLS_BRAND } }; cell.alignment = { vertical: 'middle', horizontal: 'center', wrapText: true }; cell.border = { top: { style: 'thin', color: { argb: 'FFCBD5E1' } }, bottom: { style: 'thin', color: { argb: 'FFCBD5E1' } } }; });
  hr.height = 22;
  ws.autoFilter = { from: { row: r, column: 1 }, to: { row: r, column: opts.cols.length } };
  ws.views = [{ state: 'frozen', ySplit: r }];
  return { ws, headerRowIdx: r };
}
function styleDataRow(ws, rowIdx, ncol, zebra) {
  const row = ws.getRow(rowIdx);
  row.eachCell({ includeEmpty: true }, (cell, colN) => {
    if (colN > ncol) return;
    cell.border = { bottom: { style: 'thin', color: { argb: 'FFECEEF1' } } };
    if (zebra) cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: XLS_ROW_ALT } };
  });
}
function reportHeader(req) {
  const rname = getSetting('restaurant_name') || 'QLNH';
