const upsertOrder = db.prepare(`INSERT INTO orders(uuid,table_id,code,table_names,status,discount,payment_method,note,staff_name,guests,cancel_req,extra_tables,customer_name,customer_phone,customer_note,debt_settled,debt_settled_at,discount_pct,tax_pct,apply_tax,biz_at,deposit,paid_cash,paid_transfer,debt_amount,debt_paid_cash,debt_paid_transfer,deposit_at,deposit_method,created_at,paid_at,synced,updated_at)
  VALUES(@uuid,@table_id,@code,@table_names,@status,@discount,@payment_method,@note,@staff_name,@guests,@cancel_req,@extra_tables,@customer_name,@customer_phone,@customer_note,@debt_settled,@debt_settled_at,@discount_pct,@tax_pct,@apply_tax,@biz_at,@deposit,@paid_cash,@paid_transfer,@debt_amount,@debt_paid_cash,@debt_paid_transfer,@deposit_at,@deposit_method,@created_at,@paid_at,1,@updated_at)
  ON CONFLICT(uuid) DO UPDATE SET table_id=@table_id,code=@code,table_names=@table_names,status=@status,discount=@discount,
    payment_method=@payment_method,note=@note,staff_name=@staff_name,guests=@guests,cancel_req=@cancel_req,extra_tables=@extra_tables,customer_name=@customer_name,customer_phone=@customer_phone,customer_note=@customer_note,debt_settled=@debt_settled,debt_settled_at=@debt_settled_at,discount_pct=@discount_pct,tax_pct=@tax_pct,apply_tax=@apply_tax,biz_at=@biz_at,deposit=@deposit,paid_cash=@paid_cash,paid_transfer=@paid_transfer,debt_amount=@debt_amount,debt_paid_cash=@debt_paid_cash,debt_paid_transfer=@debt_paid_transfer,deposit_at=@deposit_at,deposit_method=@deposit_method,created_at=@created_at,paid_at=@paid_at,updated_at=@updated_at,synced=1`);
function applyIncomingOrder(o) {
  if (!o.uuid) return false;
  const existing = db.prepare('SELECT id, updated_at, status FROM orders WHERE uuid=?').get(o.uuid);
  const ts = o.updated_at || nowStr();
  // Cac lan THU NO duoc GOP theo uuid rieng, LAM TRUOC va KHONG phu thuoc last-write-wins cua don.
  // Nho vay tien thu no o may quay khong bao gio mat du 2 may lech dong ho.
  const _mergedDp = mergeDebtPayments(o.uuid, o.debt_payments_all);
  // Bill da xoa/huy (void) tren may chu la trang thai cuoi -> khong cho may quay day ban cu lam "song lai"
  if (existing && existing.status === 'void' && (o.status || 'open') !== 'void') { if (_mergedDp) recalcDebt(existing.id); return 'void'; }
  if (existing && existing.updated_at && ts < existing.updated_at) { if (_mergedDp) recalcDebt(existing.id); return 'older'; } // cu hon -> bo qua (last-write-wins)
  upsertOrder.run({
    uuid: o.uuid, table_id: (o.table_id != null ? o.table_id : null), code: o.code || '', table_names: o.table_names || '', status: o.status || 'paid',
    discount: money(o.discount), payment_method: o.payment_method || null, note: o.note || '',
    staff_name: o.staff_name || '', guests: money(o.guests), cancel_req: o.cancel_req ? 1 : 0, extra_tables: o.extra_tables || '',
    customer_name: o.customer_name || null, customer_phone: o.customer_phone || null, customer_note: o.customer_note || null,
    debt_settled: (o.debt_settled != null ? (o.debt_settled ? 1 : 0) : 1), debt_settled_at: o.debt_settled_at || null, discount_pct: o.discount_pct || 0, tax_pct: (o.tax_pct != null ? o.tax_pct : null), apply_tax: o.apply_tax ? 1 : 0,
    biz_at: o.biz_at || null, deposit: money(o.deposit) || 0, paid_cash: money(o.paid_cash) || 0, paid_transfer: money(o.paid_transfer) || 0, debt_amount: money(o.debt_amount) || 0, debt_paid_cash: money(o.debt_paid_cash) || 0, debt_paid_transfer: money(o.debt_paid_transfer) || 0, deposit_at: o.deposit_at || null, deposit_method: o.deposit_method || null, created_at: o.created_at || nowStr(), paid_at: o.paid_at || null, updated_at: ts,
  });
  const row = db.prepare('SELECT id FROM orders WHERE uuid=?').get(o.uuid);
  db.prepare('DELETE FROM order_items WHERE order_id=?').run(row.id);
  for (const it of (o.items || [])) db.prepare('INSERT INTO order_items(order_id,name,price,qty,note,sent,del_req,tax) VALUES(?,?,?,?,?,?,?,?)').run(row.id, it.name, money(it.price), qtyNum(it.qty), it.note || '', it.sent ? 1 : 0, it.del_req ? 1 : 0, Number(it.tax) || 0);
  if ((o.status || 'open') === 'open' && o.table_id) db.prepare("UPDATE orders SET status='void' WHERE table_id=? AND status='open' AND uuid<>?").run(o.table_id, o.uuid);
  recalcDebt(row.id); // 4 cot tom tat luon tinh lai tu debt_payments (khong tin so may kia gui sang)
  return true;
}
app.post('/api/sync/orders', syncAuth, (req, res) => {
  const orders = (req.body && req.body.orders) || [];
  const accepted = [], rejected = [];
  for (const o of orders) {
    const r = applyIncomingOrder(o);
    if (r === true) accepted.push(o.uuid);
    else if (o && o.uuid) rejected.push({ uuid: o.uuid, reason: (typeof r === 'string' ? r : 'invalid') });
  }
  if (accepted.length) touch();
  if (rejected.length) LOG.warn('sync.reject', 'May chu tu choi ' + rejected.length + '/' + orders.length + ' don day len: ' + rejected.map(x => x.uuid.slice(0, 8) + ':' + x.reason).join(', '));
  // Tra ve server_now de may quay tu bu LECH DONG HO khi day lan sau
  res.json({ ok: true, applied: accepted.length, accepted, rejected, server_now: nowStr() });
});
