      if (cash + transfer <= 0) { cash = money(r.debt_amount); note = 'bu du lieu cu (ban cu khong luu hinh thuc thu - mac dinh tien mat)'; }
      const at = r.debt_settled_at || r.paid_at || localNowStr();
      db.prepare('INSERT INTO debt_payments(uuid,order_uuid,paid_at,cash,transfer,staff_name,note,voided,created_at,updated_at) VALUES(?,?,?,?,?,?,?,0,?,?)')
        .run(crypto.randomUUID(), r.uuid, at, cash, transfer, '', note, localNowStr(), nowStr());
      recalcDebt(r.id); n++;
    }
    console.log('Bu du lieu thu no cho', n, 'khoan no cu');
  } catch (e) { console.log('Bu thu no loi:', e.message); }
  setSetting('debt_pay_v2', '1');
}
app.listen(PORT, process.env.QLNH_HOST || '0.0.0.0', () => {
  console.log('QLNH server (' + ROLE + ') chay tai http://localhost:' + PORT + (WRITE_THROUGH ? ' [write-through ON]' : ''));
  try {
    const _don = db.prepare("SELECT COUNT(*) c FROM orders WHERE status='paid'").get().c;
    LOG.info('app.start', 'Khoi dong ' + ROLE + ' cong ' + PORT + ' | ' + _don + ' bill da thanh toan | quan: ' + (getSetting('restaurant_name') || ''));
  } catch (e) {}
  LOG.start(60000);   // moi 60s day nhat ky ve may chu ky thuat (neu da cau hinh)
});
for (const sig of ['SIGINT', 'SIGTERM']) process.on(sig, () => { try { if (REMOTE) REMOTE.stop(); } catch (e) {} process.exit(0); });
process.on('uncaughtException', (e) => { try { LOG.error('crash', String(e && e.stack || e)); } catch (x) {} console.error('LOI:', e); });
process.on('unhandledRejection', (e) => { try { LOG.error('crash.promise', String(e && e.stack || e)); } catch (x) {} });

// Bo tra loi DO TIM trong mang LAN: may quay broadcast 'QLNH_DISCOVER' -> may chu tra ve IP/cong.
// KHONG gui kem khoa dong bo (bao mat) — may quay tu xac thuc bang khoa cua no.
if (ROLE === 'central') {
  try {
    const dgram = require('dgram');
    const sock = dgram.createSocket({ type: 'udp4', reuseAddr: true });
    sock.on('message', (msg, rinfo) => {
      if (String(msg).indexOf('QLNH_DISCOVER') !== 0) return;
      const reply = Buffer.from(JSON.stringify({ qlnh: true, port: Number(PORT), name: getSetting('restaurant_name') || 'QLNH' }));
      try { sock.send(reply, rinfo.port, rinfo.address); } catch (e) {}
    });
    sock.on('error', () => { try { sock.close(); } catch (e) {} });
    sock.bind(41234, () => { try { sock.setBroadcast(true); } catch (e) {} });
  } catch (e) { console.log('discovery off:', e.message); }
}

// Ghi thong tin cho app .exe doc
try {
  const fs = require('fs');
  const { DATA_DIR } = require('./db');
  fs.writeFileSync(path.join(DATA_DIR, 'server-info.json'), JSON.stringify({ role: ROLE, port: PORT, syncKey: getSetting('sync_key') }, null, 2));
} catch (e) {}

// Khung gio cao diem (gio an) - cau hinh trong Cai dat, vd "10:00-14:00,17:00-22:00". Trong khung nay chup lien tuc hon.
function inPeakNow() {
  const raw = (getSetting('backup_peak') || '10:00-14:00,17:00-22:00').trim();
  if (!raw) return false;
  const now = new Date(); const cur = now.getHours() * 60 + now.getMinutes();
  for (const seg of raw.split(',')) {
    const m = seg.trim().match(/^(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})$/);
    if (!m) continue;
    const a = (+m[1]) * 60 + (+m[2]), b = (+m[3]) * 60 + (+m[4]);
    if (a <= b) { if (cur >= a && cur <= b) return true; } else { if (cur >= a || cur <= b) return true; } // khung qua nua dem
  }
  return false;
}
// (1) NEN: cu 15 phut chup 1 ban DU VANG KHACH (luon co ban sao dinh ky).
setInterval(() => {
  try { const dir = (getSetting('backup_dir') || '').trim(); if (dir) backup.snapshotDb(dir); }
  catch (e) { console.log('Snapshot nen 15p loi:', e.message); }
}, 15 * 60 * 1000);
// (2) GIO CAO DIEM: trong khung gio an, co giao dich moi thi chup ~2 phut/lan -> gan nhu lien tuc.
setInterval(() => {
  try {
    if (!_dirtySinceSnap) return;                         // khong co giao dich moi -> bo (nen 15p da lo)
    if (!inPeakNow()) return;                             // ngoai gio cao diem -> de nen 15p lo
    const dir = (getSetting('backup_dir') || '').trim();
    if (!dir) return;
    backup.snapshotDb(dir);
    _dirtySinceSnap = false;
  } catch (e) { console.log('Snapshot cao diem loi:', e.message); }
}, 2 * 60 * 1000);
// Tu dong sao luu hang ngay qua email
setInterval(async () => {
  try {
    const hasEmail = getSetting('backup_email') && getSetting('smtp_host');
    const dir = getSetting('backup_dir');
    if (!hasEmail && !dir) return;
    const now = new Date();
    const today = now.toISOString().slice(0, 10);
    if (now.getHours() < Number(getSetting('backup_hour') || '23')) return;
    if (getSetting('last_backup_date') === today) return;
    if (dir) { try { await backup.saveToFolder(dir); } catch (e) { console.log('Sao luu thu muc loi:', e.message); } }
    if (hasEmail) { try { await backup.emailBackup(); } catch (e) { console.log('Sao luu email loi:', e.message); } }
    setSetting('last_backup_date', today);
    audit(null, 'backup.auto', (dir ? '[folder] ' : '') + (hasEmail ? getSetting('backup_email') : ''));
  } catch (e) { console.log('Sao luu tu dong loi:', e.message); }
}, 30 * 60 * 1000);

