'use strict';
const { DatabaseSync } = require('node:sqlite');
const path = require('path');
const fs = require('fs');

const DATA_DIR = process.env.QLNH_DATA_DIR || path.join(__dirname, 'data');
if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });
const DB_PATH = path.join(DATA_DIR, 'qlnh.db');

const db = new DatabaseSync(DB_PATH);
try { db.exec('PRAGMA journal_mode = WAL;'); } catch (e) {}
// synchronous=FULL: moi lan ghi duoc fsync xuong dia -> khong mat du lieu ke ca khi mat dien
try { db.exec('PRAGMA synchronous = FULL;'); } catch (e) {}
try { db.exec('PRAGMA busy_timeout = 5000;'); } catch (e) {}
db.exec('PRAGMA foreign_keys = ON;');

db.exec(`
CREATE TABLE IF NOT EXISTS users (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  username TEXT UNIQUE NOT NULL,
  password_hash TEXT NOT NULL,
  name TEXT NOT NULL,
  role TEXT NOT NULL DEFAULT 'staff',
  active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);
CREATE TABLE IF NOT EXISTS categories (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  sort INTEGER NOT NULL DEFAULT 0,
  active INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE IF NOT EXISTS items (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  category_id INTEGER REFERENCES categories(id) ON DELETE SET NULL,
  name TEXT NOT NULL,
  price INTEGER NOT NULL DEFAULT 0,
  active INTEGER NOT NULL DEFAULT 1,
  sort INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS tables (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  area TEXT NOT NULL DEFAULT 'Khu chính',
  sort INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS orders (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  code TEXT NOT NULL,
  table_id INTEGER REFERENCES tables(id) ON DELETE SET NULL,
  table_names TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'open',
  discount INTEGER NOT NULL DEFAULT 0,
  payment_method TEXT,
  note TEXT NOT NULL DEFAULT '',
  created_by INTEGER REFERENCES users(id),
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  paid_at TEXT
);
CREATE TABLE IF NOT EXISTS order_items (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
  item_id INTEGER REFERENCES items(id) ON DELETE SET NULL,
  name TEXT NOT NULL,
  price INTEGER NOT NULL,
  qty INTEGER NOT NULL DEFAULT 1,
  note TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);
CREATE TABLE IF NOT EXISTS audit_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER,
  username TEXT,
  action TEXT NOT NULL,
  detail TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);
CREATE TABLE IF NOT EXISTS settings (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL DEFAULT ''
);
-- Cac LAN THU NO (tra gop nhieu lan). Gan voi don theo order_uuid de dong bo 2 may de dang.
-- Tien thu no duoc tinh vao dung NGAY THU (paid_at cua dong nay), khong phai ngay ban.
CREATE TABLE IF NOT EXISTS debt_payments (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  uuid TEXT,
  order_uuid TEXT NOT NULL,
  paid_at TEXT NOT NULL,
  cash INTEGER NOT NULL DEFAULT 0,
  transfer INTEGER NOT NULL DEFAULT 0,
  staff_name TEXT,
  note TEXT NOT NULL DEFAULT '',
  voided INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  updated_at TEXT
);
`);

function ensureColumns(table, defs) {
  const have = db.prepare('PRAGMA table_info(' + table + ')').all().map(function (c) { return c.name; });
  for (const d of defs) if (!have.includes(d[0])) db.exec('ALTER TABLE ' + table + ' ADD COLUMN ' + d[1]);
}
ensureColumns('orders', [
  ['uuid', 'uuid TEXT'],
  ['synced', 'synced INTEGER NOT NULL DEFAULT 0'],
  ['updated_at', 'updated_at TEXT'],
  ['staff_name', 'staff_name TEXT'],
  ['guests', 'guests INTEGER NOT NULL DEFAULT 0'],
  ['cancel_req', 'cancel_req INTEGER NOT NULL DEFAULT 0'],
  ['extra_tables', "extra_tables TEXT NOT NULL DEFAULT ''"],
  ['customer_name', 'customer_name TEXT'],
  ['customer_phone', 'customer_phone TEXT'],
  ['customer_note', 'customer_note TEXT'],
  ['debt_settled', 'debt_settled INTEGER NOT NULL DEFAULT 1'],
  ['debt_settled_at', 'debt_settled_at TEXT'],
  ['discount_pct', 'discount_pct INTEGER NOT NULL DEFAULT 0'],
  ['tax_pct', 'tax_pct REAL'],
  ['apply_tax', 'apply_tax INTEGER NOT NULL DEFAULT 0'],
  ['biz_at', 'biz_at TEXT'],
  ['deposit', 'deposit INTEGER NOT NULL DEFAULT 0'],
  ['paid_cash', 'paid_cash INTEGER NOT NULL DEFAULT 0'],
  ['paid_transfer', 'paid_transfer INTEGER NOT NULL DEFAULT 0'],
  ['debt_amount', 'debt_amount INTEGER NOT NULL DEFAULT 0'],
  ['debt_paid_cash', 'debt_paid_cash INTEGER NOT NULL DEFAULT 0'],
  ['debt_paid_transfer', 'debt_paid_transfer INTEGER NOT NULL DEFAULT 0'],
  ['deposit_at', 'deposit_at TEXT'],
  ['deposit_method', 'deposit_method TEXT'],
]);
try { db.exec('CREATE UNIQUE INDEX IF NOT EXISTS idx_orders_uuid ON orders(uuid)'); } catch (e) {}
try { db.exec('CREATE UNIQUE INDEX IF NOT EXISTS idx_debt_payments_uuid ON debt_payments(uuid)'); } catch (e) {}
try { db.exec('CREATE INDEX IF NOT EXISTS idx_debt_payments_order ON debt_payments(order_uuid)'); } catch (e) {}
ensureColumns('order_items', [['sent', 'sent INTEGER NOT NULL DEFAULT 0'], ['del_req', 'del_req INTEGER NOT NULL DEFAULT 0'], ['tax', 'tax REAL NOT NULL DEFAULT 0']]);
ensureColumns('users', [['perms', 'perms TEXT']]);
ensureColumns('categories', [['uuid', 'uuid TEXT'], ['parent', 'parent TEXT']]);
ensureColumns('items', [['uuid', 'uuid TEXT'], ['image', 'image TEXT'], ['code', 'code TEXT'], ['unit', 'unit TEXT'], ['tax', 'tax REAL'], ['cost', 'cost INTEGER NOT NULL DEFAULT 0'], ['description', 'description TEXT']]);
try { db.exec('CREATE UNIQUE INDEX IF NOT EXISTS idx_categories_uuid ON categories(uuid)'); } catch (e) {}
try { db.exec('CREATE UNIQUE INDEX IF NOT EXISTS idx_items_uuid ON items(uuid)'); } catch (e) {}
{
  const _crypto = require('crypto');
  for (const _t of ['categories', 'items']) {
    const _rows = db.prepare('SELECT id FROM ' + _t + " WHERE uuid IS NULL OR uuid=''").all();
    for (const _r of _rows) db.prepare('UPDATE ' + _t + ' SET uuid=? WHERE id=?').run(_crypto.randomUUID(), _r.id);
  }
}

function getSetting(key, def) {
  if (def === undefined) def = '';
  const row = db.prepare('SELECT value FROM settings WHERE key=?').get(key);
  return row ? row.value : def;
}
function setSetting(key, value) {
  db.prepare('INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value').run(key, String(value));
}
function audit(user, action, detail) {
  if (detail === undefined) detail = '';
  db.prepare('INSERT INTO audit_log(user_id,username,action,detail) VALUES(?,?,?,?)')
    .run(user ? user.id : null, user ? user.username : 'system', action, detail);
}

module.exports = { db, DATA_DIR, DB_PATH, getSetting, setSetting, audit };

