const path = require('path');

function seed() {
  const userCount = db.prepare('SELECT COUNT(*) c FROM users').get().c;
  if (userCount === 0) {
    const hash = (p) => hashPassword(p);
    const ins = db.prepare('INSERT INTO users(username,password_hash,name,role) VALUES(?,?,?,?)');
    ins.run('chuquan', hash('123456'), 'Chủ quán', 'owner');
    ins.run('admin', hash('admin123'), 'Quản lý', 'admin');
    ins.run('thungan', hash('123456'), 'Thu ngân', 'staff');
    console.log('Da tao tai khoan mac dinh: chuquan/123456, admin/admin123, thungan/123456');
  }

  // Nhap thuc don that tu file menu-data.json (1 lan; thay sach menu mau). Don da ban giu nguyen.
  try {
    const MENU_VERSION = 'danhmuc-2024-12-v2';
    if (getSetting('menu_imported') !== MENU_VERSION) {
      const dataPath = path.join(__dirname, 'menu-data.json');
      if (fs.existsSync(dataPath)) {
        const data = JSON.parse(fs.readFileSync(dataPath, 'utf8'));
        db.exec('BEGIN');
        try {
          db.prepare('DELETE FROM items').run();
          db.prepare('DELETE FROM categories').run();
          const insC = db.prepare('INSERT INTO categories(name,sort,active,uuid,parent) VALUES(?,?,1,?,?)');
          const catId = {};
          data.categories.forEach((c, idx) => { catId[c.name] = insC.run(c.name, idx + 1, c.uuid, c.parent || null).lastInsertRowid; });
          const insI = db.prepare('INSERT INTO items(category_id,name,price,sort,active,uuid,code,unit,tax,cost,description) VALUES(?,?,?,?,1,?,?,?,?,?,?)');
          for (const it of data.items) insI.run(catId[it.group] || null, it.name, Math.round(it.price || 0), it.sort || 0, it.uuid, it.code || '', it.unit || '', (it.tax == null ? null : it.tax), Math.round(it.cost || 0), it.desc || '');
          db.exec('COMMIT');
        } catch (e) { try { db.exec('ROLLBACK'); } catch (e2) {} throw e; }
        setSetting('menu_imported', MENU_VERSION);
        console.log('Da nhap thuc don that:', data.items.length, 'mon /', data.categories.length, 'danh muc');
      }
    }
  } catch (e) { console.log('Nhap thuc don loi:', e.message); }

  // Mot lan: BU THUE VAT cho mon cu bi thieu (DB import truoc khi menu-data.json co thue) -> tax IS NULL.
  // Chi cap nhat mon dang NULL, KHONG xoa/ghi de chinh sua cua khach. Khop theo uuid roi ten.
  if (getSetting('tax_backfill_v1') !== '1') {
    try {
      const dataPath2 = path.join(__dirname, 'menu-data.json');
      if (fs.existsSync(dataPath2)) {
        const data2 = JSON.parse(fs.readFileSync(dataPath2, 'utf8'));
        const byUuid = {}, byName = {};
        for (const it of data2.items) { if (it.tax != null) { if (it.uuid) byUuid[it.uuid] = it.tax; byName[it.name] = it.tax; } }
        const updU = db.prepare('UPDATE items SET tax=? WHERE uuid=? AND tax IS NULL');
        const updN = db.prepare('UPDATE items SET tax=? WHERE name=? AND tax IS NULL');
        let n = 0;
        for (const u in byUuid) n += updU.run(byUuid[u], u).changes;
        for (const nm in byName) n += updN.run(byName[nm], nm).changes;
        const rest = db.prepare('UPDATE items SET tax=8 WHERE tax IS NULL').run().changes; // mon le tu them -> mac dinh 8% (mon an), chu sua lai neu can
        if (n + rest > 0) console.log('Bu thue VAT:', n, 'mon khop menu +', rest, 'mon le -> 8%');
      }
    } catch (e) { console.log('Bu thue loi:', e.message); }
    setSetting('tax_backfill_v1', '1');
  }

  // Gan nhom chinh (parent) cho danh muc -> menu 2 cap (chi gan khi chua co, ton trong chinh sua admin)
  setCategoryParents();

  // Dam bao tai khoan chu quan la chuquan/123456 (sua DB cu owner/owner123). Chay 1 lan.
  if (getSetting('chuquan_pw123456') !== '1') {
    try {
      db.prepare("UPDATE users SET username='chuquan' WHERE username='owner'").run();
      const u = db.prepare("SELECT id FROM users WHERE username='chuquan'").get();
      if (u) db.prepare('UPDATE users SET password_hash=? WHERE id=?').run(hashPassword('123456'), u.id);
    } catch (e) {}
