  // Gan quyen mac dinh cho user cu chua co perms (admin: xem thong ke; staff: sua thuc don). Chay 1 lan.
  if (getSetting('perms_default_v1') !== '1') {
    try {
      const rows = db.prepare("SELECT id, role FROM users WHERE role != 'owner' AND (perms IS NULL OR perms='')").all();
      for (const u of rows) {
        const def = u.role === 'admin' ? ['stats'] : (u.role === 'staff' ? ['menu'] : []);
        db.prepare('UPDATE users SET perms=? WHERE id=?').run(JSON.stringify(def), u.id);
      }
