  const catCount = db.prepare('SELECT COUNT(*) c FROM categories').get().c;
  if (catCount === 0) {
    // uuid co dinh -> may chu va may quay khop nhau khi dong bo
    const insC = db.prepare('INSERT INTO categories(name,sort,uuid) VALUES(?,?,?)');
    const insI = db.prepare('INSERT INTO items(category_id,name,price,sort,uuid) VALUES(?,?,?,?,?)');
    const cMain = insC.run('Món chính', 1, 'cat-mon-chinh').lastInsertRowid;
