    insI.run(cDrink, 'Bia hơi', 15000, 1, 'it-bia-hoi');
    insI.run(cDrink, 'Trà đá', 5000, 2, 'it-tra-da');
    insI.run(cDrink, 'Nước ngọt', 12000, 3, 'it-nuoc-ngot');
    insI.run(cDes, 'Chè', 20000, 1, 'it-che');
    console.log('Da tao thuc don mau (tieng Viet).');
  }

  const tblCount = db.prepare('SELECT COUNT(*) c FROM tables').get().c;
  if (tblCount === 0) {
    const insT = db.prepare('INSERT INTO tables(name,area,sort) VALUES(?,?,?)');
    for (let i = 1; i <= 12; i++) insT.run('Bàn ' + i, 'Khu chính', i);
    console.log('Da tao 12 ban.');
  }

  if (!db.prepare('SELECT 1 FROM settings WHERE key=?').get('restaurant_name')) {
    setSetting('restaurant_name', 'Nhà hàng QLNH');
    setSetting('paper_size', '80');
    setSetting('jwt_secret', crypto.randomBytes(32).toString('hex'));
    setSetting('backup_email', '');
    setSetting('smtp_host', '');
    setSetting('smtp_port', '587');
    setSetting('smtp_user', '');
    setSetting('smtp_pass', '');
    setSetting('address', '');
    setSetting('phone', '');
    setSetting('receipt_footer', 'Vui lòng kiểm tra kỹ lại nội dung trước khi thanh toán!');
    setSetting('receipt_qr', '');
    setSetting('discount_note', 'nhà hàng tặng');
    setSetting('tax_rate', '0');
    console.log('Da tao cau hinh mac dinh.');
  }
  if (!getSetting('sync_key')) setSetting('sync_key', crypto.randomBytes(16).toString('hex'));

  // Khoi tao bo dem so hoa don (tang dan) theo so don hien co -> khong nhay lung tung
  if (!getSetting('order_seq')) {
    try { const c = db.prepare('SELECT COUNT(*) c FROM orders').get().c; setSetting('order_seq', String(c)); }
    catch (e) { setSetting('order_seq', '0'); }
  }

  // Don don "mo coi" (dang mo nhung mat lien ket ban do bug cu) -> tranh ban ao lech nhau
  try { db.prepare("UPDATE orders SET status='void' WHERE status='open' AND (table_id IS NULL OR table_id NOT IN (SELECT id FROM tables))").run(); } catch (e) {}

  // Gop trung + dat uuid co dinh cho thuc don mau -> 2 may khop nhau, het lap (chay moi lan khoi dong)
  fixMenuUuids();

  // Mot lan: doi ten mon/danh muc mau cu (khong dau) sang tieng Viet, GIU NGUYEN du lieu khac
  if (getSetting('vi_named') !== '1') {
    const im = { 'Pho bo': 'Phở bò', 'Com rang': 'Cơm rang', 'Ga rang': 'Gà rang', 'Bun cha': 'Bún chả', 'Nem ran': 'Nem rán', 'Bia hoi': 'Bia hơi', 'Tra da': 'Trà đá', 'Nuoc ngot': 'Nước ngọt', 'Che': 'Chè' };
    for (const k in im) db.prepare('UPDATE items SET name=? WHERE name=?').run(im[k], k);
    const cm = { 'Mon chinh': 'Món chính', 'Khai vi': 'Khai vị', 'Do uong': 'Đồ uống', 'Trang mieng': 'Tráng miệng' };
    for (const k in cm) db.prepare('UPDATE categories SET name=? WHERE name=?').run(cm[k], k);
