  const itemFix = { 'Phở bò': 'it-pho-bo', 'Cơm rang': 'it-com-rang', 'Gà rang': 'it-ga-rang', 'Bún chả': 'it-bun-cha', 'Nem rán': 'it-nem-ran', 'Salad': 'it-salad', 'Bia hơi': 'it-bia-hoi', 'Trà đá': 'it-tra-da', 'Nước ngọt': 'it-nuoc-ngot', 'Chè': 'it-che' };
  const merge = (table, map) => {
    for (const name in map) {
      const uuid = map[name];
      const rows = db.prepare('SELECT id,uuid FROM ' + table + ' WHERE name=? ORDER BY id').all(name);
      if (!rows.length) continue;
      let keeper = rows.find(r => r.uuid === uuid) || rows[0];
      // giai phong uuid dich neu dang bi dong khac giu
      db.prepare('UPDATE ' + table + ' SET uuid=? WHERE uuid=? AND id<>?').run(uuid + '-dup-' + Date.now(), uuid, keeper.id);
      if (keeper.uuid !== uuid) db.prepare('UPDATE ' + table + ' SET uuid=? WHERE id=?').run(uuid, keeper.id);
      for (const r of rows) {
        if (r.id === keeper.id) continue;
        if (table === 'categories') {
          db.prepare('UPDATE items SET category_id=? WHERE category_id=?').run(keeper.id, r.id);
          db.prepare('DELETE FROM categories WHERE id=?').run(r.id);
        } else {
          db.prepare('DELETE FROM items WHERE id=?').run(r.id);
        }
      }
