'use strict';
// Sync agent chay tren may quay (local-first):
//  - Keo danh muc/nguoi dung/ban/cau hinh tu may chu ve local
//  - Day cac don chua dong bo (synced=0) len may chu
// Khi may chu offline -> bo qua, lan sau thu lai. May quay van ban binh thuong.
const fs = require('fs');
const { db, DATA_DIR, getSetting, setSetting } = require('./db');
const { parseCandidates, makeResolver } = require('./endpoint');
const LOG = (() => { try { return require('./logger'); } catch (e) { const n = () => {}; return { info: n, warn: n, error: n }; } })();
try { db.exec('PRAGMA busy_timeout=5000'); } catch (e) {}

let status = { online: false, lastSync: null, pending: 0, lastError: '', rejected: 0 };
function getStatus() {
  status.pending = db.prepare('SELECT COUNT(*) c FROM orders WHERE synced=0').get().c;
  return status;
}
function writeStatusFile() {
  try {
    const p = process.env.QLNH_STATUS_FILE || (DATA_DIR + '/sync-status.json');
    fs.writeFileSync(p, JSON.stringify(getStatus()));
  } catch (e) {}
}

async function fetchJSON(url, key, opts) {
  opts = opts || {};
  const res = await fetch(url, {
    method: opts.method || 'GET',
    headers: Object.assign({ 'x-sync-key': key }, opts.body ? { 'Content-Type': 'application/json' } : {}),
    body: opts.body ? JSON.stringify(opts.body) : undefined,
    signal: AbortSignal.timeout(opts.timeout || 6000),
  });
  if (!res.ok) throw new Error('HTTP ' + res.status);
  return res.json();
}

function applyCatalog(cat) {
  if (Array.isArray(cat.categories))
    for (const c of cat.categories) {
      if (!c.uuid) continue;
      const ex = db.prepare('SELECT id FROM categories WHERE uuid=?').get(c.uuid);
      if (ex) db.prepare('UPDATE categories SET name=?,sort=?,active=? WHERE uuid=?').run(c.name, c.sort, c.active, c.uuid);
      else db.prepare('INSERT INTO categories(name,sort,active,uuid) VALUES(?,?,?,?)').run(c.name, c.sort, c.active, c.uuid);
    }
