    for (const i of cat.items) {
      if (!i.uuid) continue;
      const c2 = i.category_uuid ? db.prepare('SELECT id FROM categories WHERE uuid=?').get(i.category_uuid) : null;
      const catId = c2 ? c2.id : null;
      const ex = db.prepare('SELECT id FROM items WHERE uuid=?').get(i.uuid);
      if (ex) db.prepare('UPDATE items SET category_id=?,name=?,price=?,active=?,sort=?,image=? WHERE uuid=?').run(catId, i.name, i.price, i.active, i.sort, i.image || null, i.uuid);
      else db.prepare('INSERT INTO items(category_id,name,price,active,sort,uuid,image) VALUES(?,?,?,?,?,?,?)').run(catId, i.name, i.price, i.active, i.sort, i.uuid, i.image || null);
    }
  if (Array.isArray(cat.tables))
    for (const t of cat.tables) db.prepare('INSERT INTO tables(id,name,area,sort) VALUES(?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name,area=excluded.area,sort=excluded.sort').run(t.id, t.name, t.area, t.sort);
  if (Array.isArray(cat.users))
    for (const u of cat.users) {
      const ex = db.prepare('SELECT id FROM users WHERE username=?').get(u.username);
      if (ex) { db.prepare('UPDATE users SET password_hash=?,name=?,role=?,active=? WHERE username=?').run(u.password_hash, u.name, u.role, u.active, u.username); if (u.perms != null && u.perms !== '') db.prepare('UPDATE users SET perms=? WHERE username=?').run(u.perms, u.username); }
      else db.prepare('INSERT INTO users(username,password_hash,name,role,active,perms) VALUES(?,?,?,?,?,?)').run(u.username, u.password_hash, u.name, u.role, u.active, (u.perms != null ? u.perms : null));
    }
  if (cat.settings)
    for (const k of ['restaurant_name', 'paper_size'])
      if (cat.settings[k] != null) db.prepare('INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value').run(k, String(cat.settings[k]));
}

const nowStr2 = () => new Date().toISOString().replace('T', ' ').slice(0, 23);
/* ===== BU LECH DONG HO 2 MAY =====
   Moi moc thoi gian (updated_at) cua may quay duoc cong them do lech so voi may chu, tuc la
   luon quy ve GIO MAY CHU. Nho vay so sanh "ban nao moi hon" (last-write-wins) giua 2 may moi
   dung, khong con canh may quay chay cham bi may chu tu choi rui mat thao tac. */
function saveClockSkew(serverNow) {
  try {
    const sv = Date.parse(String(serverNow).replace(' ', 'T') + 'Z');
    if (!isFinite(sv)) return;
    const lo = Date.parse(nowStr2().replace(' ', 'T') + 'Z');
    const skew = sv - lo;
    if (Math.abs(skew) > 24 * 3600 * 1000) { LOG.error('clock.skew.huge', 'Dong ho 2 may lech qua 1 ngay (' + Math.round(skew / 3600000) + ' gio) - BO QUA, can chinh lai gio may'); return; }
    const cur = Number(getSetting('clock_skew_ms') || 0);
    if (Math.abs(skew - cur) > 3000) {
      setSetting('clock_skew_ms', String(Math.round(skew)));
      const lv = Math.abs(skew) > 120000 ? 'warn' : 'info';
      LOG[lv]('clock.skew', 'Dong ho may quay lech ' + Math.round(skew / 1000) + ' giay so voi may chu' + (Math.abs(skew) > 120000 ? ' - NEN chinh lai gio 2 may cho khop' : '') + ' (da tu bu)');
    }
  } catch (e) {}
}
const M = (n) => Math.round(Number(n) || 0);
// Gop cac lan THU NO theo uuid. LAM TRUOC va doc lap voi last-write-wins cua don
// -> tien thu no khong bao gio mat du 2 may lech dong ho.
function mergeDebtPaymentsLocal(orderUuid, payments) {
  if (!orderUuid || !Array.isArray(payments)) return 0;
  let n = 0;
  for (const dp of payments) {
    if (!dp || !dp.uuid) continue;
    const ex = db.prepare('SELECT id, updated_at FROM debt_payments WHERE uuid=?').get(dp.uuid);
    const ts = dp.updated_at || nowStr2();
    if (ex) {
      if (ex.updated_at && ts <= ex.updated_at) continue;
      db.prepare('UPDATE debt_payments SET order_uuid=?,paid_at=?,cash=?,transfer=?,staff_name=?,note=?,voided=?,updated_at=? WHERE uuid=?')
        .run(orderUuid, String(dp.paid_at || ''), M(dp.cash), M(dp.transfer), dp.staff_name || null, dp.note || '', dp.voided ? 1 : 0, ts, dp.uuid);
    } else {
      db.prepare('INSERT INTO debt_payments(uuid,order_uuid,paid_at,cash,transfer,staff_name,note,voided,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)')
        .run(dp.uuid, orderUuid, String(dp.paid_at || ''), M(dp.cash), M(dp.transfer), dp.staff_name || null, dp.note || '', dp.voided ? 1 : 0, dp.created_at || nowStr2(), ts);
    }
    n++;
  }
  return n;
}
function recalcDebtLocal(orderUuid) {
  const o = db.prepare('SELECT id,debt_amount FROM orders WHERE uuid=?').get(orderUuid);
  if (!o) return;
  let cash = 0, transfer = 0, last = null;
  for (const r of db.prepare('SELECT * FROM debt_payments WHERE order_uuid=?').all(orderUuid)) {
    if (r.voided) continue;
    cash += M(r.cash); transfer += M(r.transfer);
    if (!last || String(r.paid_at) > last) last = String(r.paid_at);
  }
  const debt = M(o.debt_amount);
  const settled = (debt > 0 && debt - (cash + transfer) <= 0) ? 1 : (debt > 0 ? 0 : 1);
  db.prepare('UPDATE orders SET debt_settled=?, debt_settled_at=?, debt_paid_cash=?, debt_paid_transfer=? WHERE id=?')
    .run(settled, last || null, cash, transfer, o.id);
}

let lastOrderPull = '';
function applyOrderLocal(o) {
  if (!o.uuid) return;
  const ex = db.prepare('SELECT id, updated_at, synced, status FROM orders WHERE uuid=?').get(o.uuid);
  const ts = o.updated_at || '';
  // Cac lan THU NO gop rieng theo uuid, LAM TRUOC va khong phu thuoc last-write-wins cua don
  const mergedDp = mergeDebtPaymentsLocal(o.uuid, o.debt_payments_all);
  if (ex) {
    // Bill da bi xoa/huy (void) tren may chu la trang thai cuoi -> KHONG cho song lai
    if (ex.status === 'void' && (o.status || '') !== 'void') { if (mergedDp) recalcDebtLocal(o.uuid); return; }
    // Chi giu ban LOCAL khi dang sua chua dong bo (synced=0) va moi hon. Neu local da synced=1 (khong co thay doi cho)
    // -> LUON nhan ban tu may chu (nguon hop nhat). Tranh lech thong ke khi dong ho 2 may khac nhau.
    if (ex.synced === 0 && ex.updated_at && ts <= ex.updated_at) { if (mergedDp) recalcDebtLocal(o.uuid); return; }
  }
  db.prepare('INSERT INTO orders(uuid,table_id,code,table_names,status,discount,payment_method,note,staff_name,guests,cancel_req,extra_tables,customer_name,customer_phone,customer_note,debt_settled,debt_settled_at,discount_pct,tax_pct,apply_tax,biz_at,deposit,paid_cash,paid_transfer,debt_amount,debt_paid_cash,debt_paid_transfer,deposit_at,deposit_method,created_at,paid_at,synced,updated_at) VALUES(@uuid,@table_id,@code,@table_names,@status,@discount,@payment_method,@note,@staff_name,@guests,@cancel_req,@extra_tables,@customer_name,@customer_phone,@customer_note,@debt_settled,@debt_settled_at,@discount_pct,@tax_pct,@apply_tax,@biz_at,@deposit,@paid_cash,@paid_transfer,@debt_amount,@debt_paid_cash,@debt_paid_transfer,@deposit_at,@deposit_method,@created_at,@paid_at,1,@updated_at) ON CONFLICT(uuid) DO UPDATE SET table_id=@table_id,code=@code,table_names=@table_names,status=@status,discount=@discount,payment_method=@payment_method,note=@note,staff_name=@staff_name,guests=@guests,cancel_req=@cancel_req,extra_tables=@extra_tables,customer_name=@customer_name,customer_phone=@customer_phone,customer_note=@customer_note,debt_settled=@debt_settled,debt_settled_at=@debt_settled_at,discount_pct=@discount_pct,tax_pct=@tax_pct,apply_tax=@apply_tax,biz_at=@biz_at,deposit=@deposit,paid_cash=@paid_cash,paid_transfer=@paid_transfer,debt_amount=@debt_amount,debt_paid_cash=@debt_paid_cash,debt_paid_transfer=@debt_paid_transfer,deposit_at=@deposit_at,deposit_method=@deposit_method,created_at=@created_at,paid_at=@paid_at,updated_at=@updated_at,synced=1').run({
    uuid: o.uuid, table_id: (o.table_id != null ? o.table_id : null), code: o.code || '', table_names: o.table_names || '', status: o.status || 'paid',
    discount: Math.round(o.discount || 0), payment_method: o.payment_method || null, note: o.note || '',
    staff_name: o.staff_name || '', guests: Math.round(o.guests || 0), cancel_req: o.cancel_req ? 1 : 0, extra_tables: o.extra_tables || '', customer_name: o.customer_name || null, customer_phone: o.customer_phone || null, customer_note: o.customer_note || null, debt_settled: (o.debt_settled != null ? (o.debt_settled ? 1 : 0) : 1), debt_settled_at: o.debt_settled_at || null, discount_pct: o.discount_pct || 0, tax_pct: (o.tax_pct != null ? o.tax_pct : null), apply_tax: o.apply_tax ? 1 : 0,
    biz_at: o.biz_at || null, deposit: Math.round(o.deposit || 0), paid_cash: Math.round(o.paid_cash || 0), paid_transfer: Math.round(o.paid_transfer || 0), debt_amount: Math.round(o.debt_amount || 0), debt_paid_cash: Math.round(o.debt_paid_cash || 0), debt_paid_transfer: Math.round(o.debt_paid_transfer || 0), deposit_at: o.deposit_at || null, deposit_method: o.deposit_method || null, created_at: o.created_at || '', paid_at: o.paid_at || null, updated_at: ts || new Date().toISOString().replace('T', ' ').slice(0, 23),
  });
  const row = db.prepare('SELECT id FROM orders WHERE uuid=?').get(o.uuid);
  db.prepare('DELETE FROM order_items WHERE order_id=?').run(row.id);
  for (const it of (o.items || [])) db.prepare('INSERT INTO order_items(order_id,name,price,qty,note,sent,del_req,tax) VALUES(?,?,?,?,?,?,?,?)').run(row.id, it.name, Math.round(it.price || 0), (Math.round((Number(it.qty) || 0) * 1000) / 1000), it.note || '', it.sent ? 1 : 0, it.del_req ? 1 : 0, Number(it.tax) || 0);
  recalcDebtLocal(o.uuid); // 4 cot tom tat luon tinh lai tu debt_payments
}

async function syncOnce(centralUrl, key, withCatalog) {
  if (withCatalog !== false) { const cat = await fetchJSON(centralUrl + '/api/sync/catalog', key); applyCatalog(cat); }
  // 0) May chu "Xoa toan bo du lieu" -> may quay xoa theo (lam TRUOC khi day de khong tao lai don cu)
  try {
    const w = await fetchJSON(centralUrl + '/api/sync/wipe-status', key);
    const applied = Number(getSetting('wipe_seq_applied') || 0);
    if (w && Number(w.wipe_seq || 0) > applied) {
      db.exec('DELETE FROM order_items; DELETE FROM orders;');
      setSetting('wipe_seq_applied', String(w.wipe_seq));
      lastOrderPull = '';
    }
  } catch (e) {}
  try { const t = await fetchJSON(centralUrl + '/api/sync/time', key); if (t && t.server_now) saveClockSkew(t.server_now); } catch (e) {}
  const orders = db.prepare('SELECT * FROM orders WHERE synced=0').all();
  if (orders.length) {
    const payload = orders.map(o => Object.assign({}, o, {
      items: db.prepare('SELECT name,price,qty,note,sent,del_req,tax FROM order_items WHERE order_id=?').all(o.id),
      debt_payments_all: db.prepare('SELECT uuid,paid_at,cash,transfer,staff_name,note,voided,created_at,updated_at FROM debt_payments WHERE order_uuid=?').all(o.uuid || ''),
    }));
    const r = await fetchJSON(centralUrl + '/api/sync/orders', key, { method: 'POST', body: { orders: payload }, timeout: 15000 });
    if (r && r.ok) {
      // CHI danh dau da dong bo nhung don may chu XAC NHAN da nhan. Don bi tu choi (vd lech dong ho ->
      // last-write-wins) van giu synced=0 de lan sau day lai, khong bi mat am tham.
      const acc = Array.isArray(r.accepted) ? r.accepted : null;
      const rejList = Array.isArray(r.rejected) ? r.rejected : [];
      // 'older' = may chu da co ban moi hon, 'void' = bill da bi xoa han tren may chu.
      // Ca hai deu NHUONG may chu (buoc keo don ve se ghi de ban local) -> khong day lai vo han.
      // An toan vi cac lan THU NO duoc gop rieng theo uuid, khong phu thuoc last-write-wins cua don.
      const defer = rejList.filter(x => x && (x.reason === 'older' || x.reason === 'void')).map(x => x.uuid);
      const okUuid = (u) => !acc || acc.indexOf(u) >= 0 || defer.indexOf(u) >= 0;
      const ids = orders.filter(o => okUuid(o.uuid)).map(o => o.id);
      if (ids.length) {
        const ph = ids.map(() => '?').join(',');
        db.prepare('UPDATE orders SET synced=1 WHERE id IN (' + ph + ')').run(...ids);
      }
      const stuck = rejList.filter(x => x && x.reason !== 'older' && x.reason !== 'void').length;
      status.rejected = stuck;
      status.lastError = stuck ? ('May chu chua nhan ' + stuck + ' don - se thu lai') : '';
      if (rejList.length) LOG.warn('sync.push.reject', 'May chu khong nhan ' + rejList.length + '/' + orders.length + ' don: ' + rejList.map(x => x.uuid.slice(0, 8) + ':' + x.reason).join(', ') + (stuck ? ' | ' + stuck + ' don se thu lai' : ' | da nhuong ban may chu'));
      if (defer.length) LOG.info('sync.push.defer', 'Nhuong ban may chu cho ' + defer.length + ' don (tien thu no van duoc gop rieng, khong mat)');
      if (r.server_now) saveClockSkew(r.server_now);
    }
  }
  // 3) keo don tu may chu ve (dong bo 2 chieu: vd may chu duyet huy -> may quay nhan)
  try {
    const pr = await fetchJSON(centralUrl + '/api/sync/orders/pull?since=' + encodeURIComponent(lastOrderPull), key);
    if (pr && Array.isArray(pr.orders)) { for (const o of pr.orders) applyOrderLocal(o); if (pr.now) lastOrderPull = pr.now; }
  } catch (e) {}
  status.online = true; status.lastSync = new Date().toISOString(); status.lastError = '';
  return getStatus();
}

function startAgent(opts) {
  const candidates = (opts.centralUrls && opts.centralUrls.length)
    ? opts.centralUrls.map((u) => String(u).replace(/\/+$/, '')).filter(Boolean)
    : [String(opts.centralUrl || '').replace(/\/+$/, '')].filter(Boolean);
  const key = opts.key || '';
  const interval = opts.intervalMs || 2000;
  const onStatus = opts.onStatus || (() => {});
  const resolver = makeResolver(candidates);
  let tickN = 0;
  const tick = async () => {
    if (!candidates.length || !key) { status.online = false; status.lastError = 'Chua cau hinh may chu'; }
    else {
      const url = await resolver.resolve();
      const wasOnline = status.online;
      try {
        await syncOnce(url, key, (tickN % 15 === 0)); // keo thuc don ~30s/lan, keo don moi tick
        if (!wasOnline) LOG.info('sync.online', 'Da ket noi lai may chu (' + url + ')');
      } catch (e) {
        status.online = false; status.lastError = String(e.message || e); resolver.invalidate();
        if (wasOnline) LOG.warn('sync.offline', 'Mat ket noi may chu: ' + String(e.message || e) + ' | dang cho ' + status.pending + ' don');
      }
      tickN++;
    }
    writeStatusFile(); onStatus(getStatus());
  };
  tick();
  return setInterval(tick, interval);
}

module.exports = { startAgent, syncOnce, getStatus, applyCatalog, applyOrderLocal };

if (require.main === module) {
  startAgent({
    centralUrls: parseCandidates(process.env.QLNH_CENTRAL_URLS || process.env.QLNH_CENTRAL_URL),
    key: process.env.QLNH_SYNC_KEY,
    onStatus: (s) => console.log('[sync]', JSON.stringify(s)),
  });
}

