'use strict';
// Bo "chon duong" cho may quay: uu tien dia chi dau (LAN), khong toi duoc thi nhay sang dia chi sau (internet),
// va tu quay lai LAN khi LAN song tro lai (re-probe moi ~12s).
function parseCandidates(envStr) {
  return String(envStr || '')
    .split(',')
    .map((s) => s.trim().replace(/\/+$/, ''))
    .filter(Boolean);
}

function makeResolver(candidates, opts) {
  opts = opts || {};
  const ttl = opts.ttl || 12000;
  const timeout = opts.timeout || 2500;
  let active = '';
  let lastCheck = 0;

  async function probe(u) {
    try {
      const r = await fetch(u + '/api/version', { signal: AbortSignal.timeout(timeout) });
      return r.ok;
    } catch (e) {
      return false;
    }
  }

  async function resolve() {
    if (!candidates.length) return '';
    const now = Date.now();
    if (active && now - lastCheck < ttl) return active;
    for (const u of candidates) {
      if (await probe(u)) { active = u; lastCheck = now; return u; }
    }
    // Khong cai nao toi duoc -> tra cai dau (se loi -> offline, luu tam)
    lastCheck = now; active = candidates[0]; return active;
  }

  function invalidate() { active = ''; lastCheck = 0; }

  return { resolve, invalidate, candidates };
}

module.exports = { parseCandidates, makeResolver };

