'use strict';
const { db, getSetting, DATA_DIR, DB_PATH } = require('./db');
const fs = require('fs');
const path = require('path');

async function buildExcel() {
  const ExcelJS = require('exceljs');
  const wb = new ExcelJS.Workbook();
  wb.creator = 'QLNH';
  wb.created = new Date();

  const fmtMoney = '#,##0';

  // Đơn hàng
  const wsO = wb.addWorksheet('Đơn hàng');
  wsO.columns = [
    { header: 'Mã đơn', key: 'code', width: 16 },
    { header: 'Bàn', key: 'table_names', width: 16 },
    { header: 'Trạng thái', key: 'status', width: 12 },
    { header: 'Tạm tính', key: 'subtotal', width: 14, style: { numFmt: fmtMoney } },
    { header: 'Giảm giá', key: 'discount', width: 12, style: { numFmt: fmtMoney } },
    { header: 'Thành tiền', key: 'total', width: 14, style: { numFmt: fmtMoney } },
    { header: 'Thanh toán', key: 'payment_method', width: 12 },
    { header: 'Nhân viên', key: 'staff', width: 16 },
    { header: 'Tạo lúc', key: 'created_at', width: 20 },
    { header: 'Thanh toán lúc', key: 'paid_at', width: 20 },
  ];
  const orders = db.prepare('SELECT * FROM orders ORDER BY id').all();
  for (const o of orders) {
    const sub = db.prepare('SELECT COALESCE(SUM(price*qty),0) t FROM order_items WHERE order_id=?').get(o.id).t;
    const staff = db.prepare('SELECT name FROM users WHERE id=?').get(o.created_by);
    wsO.addRow({
      code: o.code, table_names: o.table_names, status: o.status,
      subtotal: sub, discount: o.discount, total: Math.max(0, sub - o.discount),
      payment_method: o.payment_method || '', staff: staff ? staff.name : '',
      created_at: o.created_at, paid_at: o.paid_at || '',
    });
  }
  wsO.getRow(1).font = { bold: true };

  // Chi tiết món
  const wsI = wb.addWorksheet('Chi tiết món');
  wsI.columns = [
    { header: 'Mã đơn', key: 'code', width: 16 },
    { header: 'Món', key: 'name', width: 24 },
    { header: 'Đơn giá', key: 'price', width: 12, style: { numFmt: fmtMoney } },
    { header: 'SL', key: 'qty', width: 8 },
    { header: 'Thành tiền', key: 'amount', width: 14, style: { numFmt: fmtMoney } },
    { header: 'Ghi chú', key: 'note', width: 20 },
  ];
  const lines = db.prepare(`SELECT oi.*, o.code FROM order_items oi JOIN orders o ON o.id=oi.order_id ORDER BY oi.order_id, oi.id`).all();
  for (const l of lines) wsI.addRow({ code: l.code, name: l.name, price: l.price, qty: l.qty, amount: l.price * l.qty, note: l.note });
  wsI.getRow(1).font = { bold: true };

  // Thực đơn
  const wsM = wb.addWorksheet('Thực đơn');
  wsM.columns = [
    { header: 'Danh mục', key: 'cat', width: 18 },
    { header: 'Món', key: 'name', width: 24 },
    { header: 'Giá', key: 'price', width: 12, style: { numFmt: fmtMoney } },
    { header: 'Hiện', key: 'active', width: 8 },
  ];
  const items = db.prepare(`SELECT i.*, c.name cat FROM items i LEFT JOIN categories c ON c.id=i.category_id ORDER BY i.sort,i.id`).all();
  for (const it of items) wsM.addRow({ cat: it.cat || '', name: it.name, price: it.price, active: it.active ? 'x' : '' });
  wsM.getRow(1).font = { bold: true };

  // Nhân viên
  const wsU = wb.addWorksheet('Nhân viên');
  wsU.columns = [
    { header: 'Tài khoản', key: 'username', width: 16 },
    { header: 'Tên', key: 'name', width: 20 },
    { header: 'Vai trò', key: 'role', width: 12 },
    { header: 'Hoạt động', key: 'active', width: 10 },
  ];
  const users = db.prepare('SELECT username,name,role,active FROM users ORDER BY id').all();
  for (const u of users) wsU.addRow({ username: u.username, name: u.name, role: u.role, active: u.active ? 'x' : '' });
  wsU.getRow(1).font = { bold: true };

  return Buffer.from(await wb.xlsx.writeBuffer());
}

async function emailBackup() {
  const nodemailer = require('nodemailer');
  const to = getSetting('backup_email');
  const host = getSetting('smtp_host');
  const port = Number(getSetting('smtp_port') || 587);
  const user = getSetting('smtp_user');
  const pass = (getSetting('smtp_pass') || '').replace(/\s+/g, ''); // bo dau cach (app password Gmail hay co)
  if (!to) throw new Error('Chưa nhập email nhận sao lưu');
  if (!host || !user || !pass) throw new Error('Chưa nhập đủ SMTP (máy chủ / tài khoản / mật khẩu ứng dụng)');

  const buf = await buildExcel();
  const transporter = nodemailer.createTransport({ host, port, secure: port === 465, requireTLS: port === 587, auth: { user, pass } });
  try { await transporter.verify(); }
  catch (e) {
    const m = String((e && e.message) || e);
    if (/invalid login|auth|535|credential|username and password|password not accepted/i.test(m))
      throw new Error('Sai tài khoản hoặc mật khẩu ứng dụng. Gmail: bật bảo mật 2 lớp rồi tạo "Mật khẩu ứng dụng" 16 ký tự, dán KHÔNG có dấu cách.');
    if (/ENOTFOUND|EAI_AGAIN|getaddrinfo/i.test(m))
      throw new Error('Không tìm thấy máy chủ SMTP — kiểm tra ô "Máy chủ SMTP" (vd smtp.gmail.com) và mạng internet.');
    if (/ETIMEDOUT|ECONNREFUSED|ECONNECTION|timeout/i.test(m))
      throw new Error('Không kết nối được SMTP — kiểm tra cổng (587 hoặc 465) và tường lửa.');
    throw new Error('Lỗi SMTP: ' + m);
  }
  const name = getSetting('restaurant_name') || 'QLNH';
  const stamp = new Date().toLocaleString('vi-VN');
  await transporter.sendMail({
    from: user, to,
    subject: '[' + name + '] Sao lưu dữ liệu ' + stamp,
    text: 'Bản sao lưu dữ liệu nhà hàng đính kèm. Tạo lúc ' + stamp + '.',
    attachments: [{ filename: 'qlnh-backup-' + Date.now() + '.xlsx', content: buf }],
  });
  return { to };
}

// Luu file Excel vao mot thu muc (KHONG can email/mat khau). Tro vao thu muc OneDrive/Drive -> tu len may.
async function saveToFolder(dir) {
  const fs = require('fs'); const path = require('path');
  dir = (dir || getSetting('backup_dir') || '').trim();
  if (!dir) throw new Error('Chưa nhập thư mục lưu sao lưu');
  try { fs.mkdirSync(dir, { recursive: true }); } catch (e) { throw new Error('Không tạo/ghi được thư mục: ' + dir); }
  const buf = await buildExcel();
  const d = new Date(); const p2 = (n) => String(n).padStart(2, '0');
  const fname = 'qlnh-backup-' + d.getFullYear() + p2(d.getMonth() + 1) + p2(d.getDate()) + '-' + p2(d.getHours()) + p2(d.getMinutes()) + '.xlsx';
  const fp = path.join(dir, fname);
  try { fs.writeFileSync(fp, buf); } catch (e) { throw new Error('Không ghi được file vào thư mục: ' + dir); }
  return { path: fp };
}


// ============ SAO LƯU / PHỤC HỒI FILE .db (phục hồi được) ============
// Nhãn máy trong tên file -> 2 máy sao lưu chung 1 thư mục cũng KHÔNG đè/xóa nhau.
const MACHINE = (process.env.QLNH_ROLE === 'local') ? 'may-quay' : 'may-chu';
// khớp cả file cũ (không nhãn) lẫn mới: qlnh-[may-chu|may-quay-]YYYYMMDD-HHMMSS[-dN].db
const BK_RE = /^qlnh-(?:(may-chu|may-quay)-)?(\d{8})-(\d{6})(?:-d(\d+))?\.db$/;
function parseBk(f) { const m = String(f).match(BK_RE); if (!m) return null; return { tag: m[1] || '', date: m[2], time: m[3], count: (m[4] != null ? Number(m[4]) : null), stamp: m[2] + m[3] }; }

// Chụp bản .db sạch (VACUUM INTO an toàn khi đang chạy). Tên: qlnh-<máy>-<giờ>-d<số đơn>.db
function snapshotDb(dir) {
  dir = (dir || getSetting('backup_dir') || '').trim();
  if (!dir) throw new Error('Chưa cấu hình thư mục sao lưu (Cài đặt).');
  fs.mkdirSync(dir, { recursive: true });
  const d = new Date(); const p2 = (n) => String(n).padStart(2, '0');
  const stamp = d.getFullYear() + p2(d.getMonth() + 1) + p2(d.getDate()) + '-' + p2(d.getHours()) + p2(d.getMinutes()) + p2(d.getSeconds());
  let cnt = 0; try { cnt = db.prepare("SELECT COUNT(*) c FROM orders WHERE status='paid'").get().c; } catch (e) {}
  const fp = path.join(dir, 'qlnh-' + MACHINE + '-' + stamp + '-d' + cnt + '.db');
  const tmp = fp + '.tmp';
  try { fs.unlinkSync(tmp); } catch (e) {}
  db.exec("VACUUM INTO '" + tmp.replace(/'/g, "''") + "'");
  fs.renameSync(tmp, fp);   // đổi tên (nguyên tử) -> file cloud không bị đẩy lúc đang ghi dở
  try { pruneBackups(dir); } catch (e) {}
  return { path: fp, name: path.basename(fp) };
}

// Dọn xoay vòng — CHỈ dọn bản của CHÍNH máy này (theo nhãn) -> không xóa bản máy kia.
function pruneBackups(dir) {
  let all; try { all = fs.readdirSync(dir); } catch (e) { return; }
  const files = all.filter(f => { const b = parseBk(f); return b && b.tag === MACHINE; }).sort();
  if (files.length <= 30) return;
  const keep = new Set(); files.slice(-30).forEach(f => keep.add(f));
  const byHour = {}, byDay = {};
  for (const f of files) { const b = parseBk(f); const day = b.date, hour = b.date + b.time.slice(0, 2); if (!byHour[hour] || f > byHour[hour]) byHour[hour] = f; if (!byDay[day] || f > byDay[day]) byDay[day] = f; }
  Object.keys(byHour).sort().slice(-72).forEach(h => keep.add(byHour[h]));
  Object.keys(byDay).sort().slice(-60).forEach(dd => keep.add(byDay[dd]));
  for (const f of files) if (!keep.has(f)) { try { fs.unlinkSync(path.join(dir, f)); } catch (e) {} }
}

function listBackups(dir) {
  dir = (dir || getSetting('backup_dir') || '').trim();
  if (!dir) return [];
  let all; try { all = fs.readdirSync(dir); } catch (e) { return []; }
  const items = all.map(f => { const b = parseBk(f); if (!b) return null; let st = {}; try { st = fs.statSync(path.join(dir, f)); } catch (e) {} return { name: f, tag: b.tag || 'may-chu', machine: (b.tag === 'may-quay' ? 'Máy quầy' : 'Máy chủ'), orders: b.count, stamp: b.stamp, size: st.size || 0, mtime: st.mtime || null }; }).filter(Boolean);
  items.sort((a, b) => a.stamp < b.stamp ? 1 : (a.stamp > b.stamp ? -1 : 0));
  return items.slice(0, 80);
}

// Kiểm tra 1 file có phải CSDL QLNH hợp lệ không (mở chỉ-đọc, xem đủ bảng chính).
function validateDb(fp) {
  if (!fs.existsSync(fp)) throw new Error('Không thấy file: ' + fp);
  const { DatabaseSync } = require('node:sqlite');
  let t;
  try { t = new DatabaseSync(fp, { readOnly: true }); } catch (e) { throw new Error('Không mở được file (có thể hỏng hoặc không phải .db).'); }
  try {
    for (const tb of ['orders', 'order_items', 'items', 'users', 'settings']) {
      const r = t.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name=?").get(tb);
      if (!r) throw new Error('File không phải CSDL QLNH hợp lệ (thiếu bảng "' + tb + '").');
    }
    const cnt = t.prepare('SELECT COUNT(*) c FROM orders').get().c;
    const users = t.prepare('SELECT COUNT(*) c FROM users').get().c;
    return { orders: cnt, users };
  } finally { try { t.close(); } catch (e) {} }
}

// Chuẩn bị phục hồi: copy file .db vào restore-pending.db; sẽ được thay ở LẦN KHỞI ĐỘNG SAU (main.js).
function stageRestore(fp) {
  const info = validateDb(fp);   // kiểm tra trước, sai thì ném lỗi (không đụng vào DB hiện tại)
  const pending = path.join(DATA_DIR, 'restore-pending.db');
  fs.copyFileSync(fp, pending);
  return info;
}

module.exports = { buildExcel, emailBackup, saveToFolder, snapshotDb, pruneBackups, listBackups, validateDb, stageRestore };

