'use strict';
/* ===== GHI LOG CHI TIET + TU DAY VE MAY CHU KY THUAT =====
   Muc dich: khi khach bao "tien bi lech" ma khong mo ta ro, ta co nhat ky day du
   moi thao tac dong toi tien de dung lai dung tinh huong.
   Nguyen tac:
   - KHONG BAO GIO lam sap app: moi thu boc try/catch, ghi file dong bo (nhanh), day mang bat dong bo.
   - KHONG gui thong tin nhay cam: khong gui mat khau, khong gui khoa dong bo, khong gui ten/SDT khach
     (chi gui do dai + 3 ky tu dau de doi chieu khi can).
   - Offline van ghi day du xuong file; hang doi giu lai, online thi day tiep. */
const fs = require('fs');
const path = require('path');
const { DATA_DIR, getSetting } = require('./db');

const LOG_DIR = path.join(DATA_DIR, 'logs');
try { fs.mkdirSync(LOG_DIR, { recursive: true }); } catch (e) {}
const QUEUE = path.join(LOG_DIR, 'queue.jsonl');
const KEEP_DAYS = 14;
const QUEUE_MAX = 5000;        // toi da so dong cho gui (tranh phinh file khi mat mang lau)
const BATCH = 200;

const ROLE = process.env.QLNH_ROLE || 'central';
let APP_VERSION = process.env.QLNH_APP_VERSION || '';
let machineId = '';
try { machineId = require('./license').getMachineId(); } catch (e) { machineId = ''; }

function stamp() {
  const d = new Date(); const p = (n) => String(n).padStart(2, '0');
  return d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate()) + ' ' + p(d.getHours()) + ':' + p(d.getMinutes()) + ':' + p(d.getSeconds());
}
function dayKey() { return stamp().slice(0, 10).replace(/-/g, ''); }
// Che bot thong tin ca nhan cua khach truoc khi gui di
function mask(v) {
  const s = String(v == null ? '' : v).trim();
  if (!s) return '';
  return s.slice(0, 3) + '***(' + s.length + ')';
}

let _lastPrune = '';
function pruneOld() {
  const today = dayKey();
  if (_lastPrune === today) return;
  _lastPrune = today;
  try {
    const keep = new Date(Date.now() - KEEP_DAYS * 86400000);
    const lim = keep.getFullYear() + String(keep.getMonth() + 1).padStart(2, '0') + String(keep.getDate()).padStart(2, '0');
    for (const f of fs.readdirSync(LOG_DIR)) {
      const m = f.match(/^qlnh-(\d{8})\.log$/);
      if (m && m[1] < lim) { try { fs.unlinkSync(path.join(LOG_DIR, f)); } catch (e) {} }
    }
  } catch (e) {}
}

function log(level, event, detail, extra) {
  let line;
  try {
    const rec = {
      t: stamp(), lv: level || 'info', ev: String(event || ''),
      d: (detail == null ? '' : String(detail)).slice(0, 800),
      role: ROLE, mid: machineId, ver: APP_VERSION,
    };
    if (extra && typeof extra === 'object') rec.x = extra;
    line = JSON.stringify(rec);
  } catch (e) { return; }
  try { pruneOld(); fs.appendFileSync(path.join(LOG_DIR, 'qlnh-' + dayKey() + '.log'), line + '\n'); } catch (e) {}
  try {
    if (getSetting('log_url')) {
      fs.appendFileSync(QUEUE, line + '\n');
      // cat bot neu hang doi qua dai
      const st = fs.statSync(QUEUE);
      if (st.size > 4 * 1024 * 1024) {
        const keep = fs.readFileSync(QUEUE, 'utf8').split('\n').filter(Boolean).slice(-QUEUE_MAX);
        fs.writeFileSync(QUEUE, keep.join('\n') + '\n');
      }
    }
  } catch (e) {}
}
const info = (ev, d, x) => log('info', ev, d, x);
const warn = (ev, d, x) => log('warn', ev, d, x);
const error = (ev, d, x) => log('error', ev, d, x);

let _sending = false;
async function flush() {
  if (_sending) return { ok: false, reason: 'dang gui' };
  const url = String(getSetting('log_url') || '').trim();
  if (!url) return { ok: false, reason: 'chua cau hinh' };
  let lines = [];
  try { lines = fs.readFileSync(QUEUE, 'utf8').split('\n').filter(Boolean); } catch (e) { return { ok: true, sent: 0 }; }
  if (!lines.length) return { ok: true, sent: 0 };
  _sending = true;
  const batch = lines.slice(0, BATCH);
  try {
    const res = await fetch(url.replace(/\/+$/, '') + '/ingest', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-log-key': String(getSetting('log_key') || '') },
      body: JSON.stringify({
        machine: machineId, role: ROLE, ver: APP_VERSION,
        shop: String(getSetting('restaurant_name') || '').slice(0, 60),
        lines: batch.map(l => { try { return JSON.parse(l); } catch (e) { return null; } }).filter(Boolean),
      }),
      signal: AbortSignal.timeout(15000),
    });
    if (!res.ok) throw new Error('HTTP ' + res.status);
    try { fs.writeFileSync(QUEUE, lines.slice(batch.length).join('\n') + (lines.length > batch.length ? '\n' : '')); } catch (e) {}
    _sending = false;
    return { ok: true, sent: batch.length, left: Math.max(0, lines.length - batch.length) };
  } catch (e) {
    _sending = false;
    return { ok: false, reason: String(e.message || e), left: lines.length };
  }
}

let timer = null;
function start(intervalMs) {
  if (timer) return timer;
  timer = setInterval(() => { flush().catch(() => {}); }, intervalMs || 60000);
  if (timer.unref) timer.unref();
  return timer;
}
function setVersion(v) { APP_VERSION = String(v || ''); }
function listFiles() {
  try {
    return fs.readdirSync(LOG_DIR).filter(f => /^qlnh-\d{8}\.log$/.test(f)).sort().reverse()
      .map(f => ({ file: f, size: fs.statSync(path.join(LOG_DIR, f)).size }));
  } catch (e) { return []; }
}
function readFile(name, maxLines) {
  if (!/^qlnh-\d{8}\.log$/.test(String(name || ''))) return [];   // chan path traversal
  try {
    const txt = fs.readFileSync(path.join(LOG_DIR, name), 'utf8');
    const arr = txt.split('\n').filter(Boolean);
    return arr.slice(-(maxLines || 500)).map(l => { try { return JSON.parse(l); } catch (e) { return { t: '', lv: 'raw', ev: '', d: l }; } });
  } catch (e) { return []; }
}
function queueSize() { try { return fs.readFileSync(QUEUE, 'utf8').split('\n').filter(Boolean).length; } catch (e) { return 0; } }

module.exports = { log, info, warn, error, flush, start, mask, setVersion, listFiles, readFile, queueSize, LOG_DIR, machineId: () => machineId };

