'use strict';
// Bản quyền theo MÃ MÁY, kích hoạt OFFLINE bằng chữ ký số Ed25519.
// App chỉ có KHÓA CÔNG KHAI -> khách/kẻ khác KHÔNG tự tạo được mã kích hoạt.
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const { DATA_DIR } = require('./db');

const PUBLIC_KEY = `-----BEGIN PUBLIC KEY-----
MCowBQYDK2VwAyEAO60Mag6WaC4llNDENiri0sLOV54jKA+tPuX2W6chQaw=
-----END PUBLIC KEY-----`;

const GRACE_DAYS = 30;                       // số ngày dùng thử trước khi chặn
const LIC_FILE = path.join(DATA_DIR, 'license.json');

function machineRaw() {
  let guid = '';
  try {
    if (process.platform === 'win32') {
      const out = require('child_process').execSync('reg query "HKLM\\SOFTWARE\\Microsoft\\Cryptography" /v MachineGuid', { timeout: 4000, windowsHide: true }).toString();
      const m = out.match(/MachineGuid\s+REG_SZ\s+([\w-]+)/i);
      if (m) guid = m[1];
    }
  } catch (e) {}
  if (!guid) {
    const os = require('os'); const ifs = os.networkInterfaces(); let mac = '';
    for (const n in ifs) for (const a of (ifs[n] || [])) if (!a.internal && a.mac && a.mac !== '00:00:00:00:00:00') { mac = a.mac; break; }
    guid = require('os').hostname() + '|' + mac;
  }
  return guid + '|' + require('os').hostname();
}
function getMachineId() {
  const h = crypto.createHash('sha256').update('QLNH-2026|' + machineRaw()).digest('hex').toUpperCase();
  return h.slice(0, 4) + '-' + h.slice(4, 8) + '-' + h.slice(8, 12) + '-' + h.slice(12, 16);
}

// Kiểm tra 1 mã kích hoạt cho máy hiện tại. key = base64url(payload).sigBase64url; payload = {mid, exp(0=vĩnh viễn), name?}
function verifyKey(key, mid) {
  try {
    const parts = String(key || '').trim().split('.');
    if (parts.length !== 2 || !parts[0] || !parts[1]) return { ok: false };
    const ok = crypto.verify(null, Buffer.from(parts[0]), crypto.createPublicKey(PUBLIC_KEY), Buffer.from(parts[1], 'base64url'));
    if (!ok) return { ok: false, reason: 'sai' };
    const p = JSON.parse(Buffer.from(parts[0], 'base64url').toString());
    if (p.mid !== mid) return { ok: false, reason: 'khac-may' };
    if (p.exp && Number(p.exp) < Date.now()) return { ok: false, reason: 'het-han' };
    return { ok: true, exp: Number(p.exp) || 0, name: p.name || '' };
  } catch (e) { return { ok: false }; }
}

function loadLic() { try { return JSON.parse(fs.readFileSync(LIC_FILE, 'utf8')); } catch (e) { return {}; } }
function saveLic(o) { try { fs.writeFileSync(LIC_FILE, JSON.stringify(o)); } catch (e) {} }

function status() {
  const mid = getMachineId();
  const lic = loadLic();
  if (!lic.firstRun) { lic.firstRun = Date.now(); saveLic(lic); }
  const v = lic.key ? verifyKey(lic.key, mid) : { ok: false };
  const graceEnd = (lic.firstRun || Date.now()) + GRACE_DAYS * 86400000;
  const trialLeft = Math.max(0, Math.ceil((graceEnd - Date.now()) / 86400000));
  return {
    machine_id: mid,
    activated: v.ok,
    permanent: !!(v.ok && !v.exp),
    exp: v.exp || 0,
    trial_days_left: v.ok ? null : trialLeft,
    blocked: !v.ok && trialLeft <= 0,
    grace_days: GRACE_DAYS,
  };
}
function activate(key) {
  const mid = getMachineId();
  const v = verifyKey(key, mid);
  if (!v.ok) throw new Error(v.reason === 'khac-may' ? 'Mã kích hoạt này KHÔNG dành cho máy này (sai mã máy).' : (v.reason === 'het-han' ? 'Mã kích hoạt đã hết hạn.' : 'Mã kích hoạt không hợp lệ.'));
  const lic = loadLic(); lic.key = String(key).trim(); saveLic(lic);
  return status();
}

module.exports = { getMachineId, verifyKey, status, activate, PUBLIC_KEY };

