'use strict';
/* ===== HO TRO TU XA: mo mot duong ham HTTPS thang vao app cua quan =====
   Cach dung: chu quan bam "Bat ho tro tu xa" -> app tu mo duong ham Cloudflare,
   hien ra 1 dia chi https ngau nhien + 1 MA KY THUAT 6 so. Chu quan gui 2 thu do
   qua Zalo. Nguoi lam phan mem mo link tren dien thoai la thay DUNG app cua quan.
   KHONG can tai khoan Cloudflare, KHONG can dung may chu nao.
   An toan:
   - Mac dinh TAT. Bat roi tu tat sau 2 gio (hoac bam tat tay).
   - Moi lan bat sinh MA KY THUAT moi. Vao qua link phai nhap ma nay TRUOC man hinh dang nhap.
   - Chi mo duong ham toi cong cua app tren may nay, khong mo gi khac. */
const fs = require('fs');
const path = require('path');
const os = require('os');
const { spawn } = require('child_process');
const { DATA_DIR } = require('./db');

const TOOLS = path.join(DATA_DIR, 'tools');
const IS_WIN = process.platform === 'win32';
const BIN = path.join(TOOLS, IS_WIN ? 'cloudflared.exe' : 'cloudflared');
function assetName() {
  const a = os.arch();
  if (IS_WIN) return a === 'arm64' ? 'cloudflared-windows-arm64.exe' : (a === 'ia32' ? 'cloudflared-windows-386.exe' : 'cloudflared-windows-amd64.exe');
  if (process.platform === 'darwin') return a === 'arm64' ? 'cloudflared-darwin-arm64.tgz' : 'cloudflared-darwin-amd64.tgz';
  return a === 'arm64' ? 'cloudflared-linux-arm64' : 'cloudflared-linux-amd64';
}
const DL_URL = 'https://github.com/cloudflare/cloudflared/releases/latest/download/' + assetName();

let st = {
  running: false, url: '', code: '', started_at: null, expires_at: null,
  downloading: false, dl_pct: 0, error: '', minutes: 120,
};
let proc = null, offTimer = null, log = () => {};
function setLogger(fn) { if (typeof fn === 'function') log = fn; }
function status() {
  const s = Object.assign({}, st);
  s.has_tool = hasTool();
  s.left_min = st.expires_at ? Math.max(0, Math.round((st.expires_at - Date.now()) / 60000)) : 0;
  return s;
}
function hasTool() { try { return fs.existsSync(BIN) && fs.statSync(BIN).size > 1000000; } catch (e) { return false; } }

// Tai cloudflared ve thu muc du lieu (chi lam 1 lan, khi chu quan bat lan dau)
async function ensureTool() {
  if (hasTool()) return true;
  if (st.downloading) throw new Error('Dang tai cong cu, doi chut');
  try { fs.mkdirSync(TOOLS, { recursive: true }); } catch (e) {}
  st.downloading = true; st.dl_pct = 0; st.error = '';
  const tmp = BIN + '.tai';
  try {
    const res = await fetch(DL_URL, { redirect: 'follow', signal: AbortSignal.timeout(600000) });
    if (!res.ok || !res.body) throw new Error('HTTP ' + res.status);
    const total = Number(res.headers.get('content-length') || 0);
    let got = 0;
    const out = fs.createWriteStream(tmp);
    for await (const chunk of res.body) {
      got += chunk.length;
      if (total) st.dl_pct = Math.min(99, Math.round(got * 100 / total));
      if (!out.write(chunk)) await new Promise(r => out.once('drain', r));
    }
    await new Promise((r, j) => { out.end(); out.on('finish', r); out.on('error', j); });
    if (fs.statSync(tmp).size < 1000000) throw new Error('File tai ve khong hop le');
    try { fs.rmSync(BIN, { force: true }); } catch (e) {}
    fs.renameSync(tmp, BIN);
    if (!IS_WIN) { try { fs.chmodSync(BIN, 0o755); } catch (e) {} }
    st.dl_pct = 100; st.downloading = false;
    log('info', 'remote.tool', 'Da tai cong cu duong ham (' + Math.round(fs.statSync(BIN).size / 1048576) + ' MB)');
    return true;
  } catch (e) {
    st.downloading = false; st.error = 'Khong tai duoc cong cu: ' + (e.message || e);
    try { fs.rmSync(tmp, { force: true }); } catch (x) {}
    log('error', 'remote.tool.fail', st.error);
    throw new Error(st.error);
  }
}

function genCode() { return String(Math.floor(100000 + Math.random() * 900000)); }

async function start(port, minutes) {
  if (st.running) return status();
  await ensureTool();
  st.minutes = Math.max(10, Math.min(720, Number(minutes) || 120));
  st.error = ''; st.url = ''; st.code = genCode();
  return await new Promise((resolve, reject) => {
    let done = false;
    try {
      proc = spawn(BIN, ['tunnel', '--no-autoupdate', '--url', 'http://127.0.0.1:' + port], { windowsHide: true });
    } catch (e) { return reject(new Error('Khong chay duoc cong cu: ' + e.message)); }
    const onData = (buf) => {
      const s = String(buf);
      const m = s.match(/https:\/\/[a-z0-9-]+\.trycloudflare\.com/i);
      if (m && !done) {
        done = true;
        st.running = true; st.url = m[0]; st.started_at = Date.now();
        st.expires_at = Date.now() + st.minutes * 60000;
        clearTimeout(offTimer);
        offTimer = setTimeout(() => { log('info', 'remote.autoclose', 'Tu dong dong cong ho tro tu xa sau ' + st.minutes + ' phut'); stop(); }, st.minutes * 60000);
        log('warn', 'remote.open', 'MO cong ho tro tu xa: ' + st.url + ' (tu dong dong sau ' + st.minutes + ' phut)');
        resolve(status());
      }
    };
    proc.stdout.on('data', onData);
    proc.stderr.on('data', onData);
    proc.on('exit', (c) => {
      const wasRunning = st.running;
      st.running = false; st.url = ''; proc = null; clearTimeout(offTimer);
      if (!done) { done = true; st.error = 'Duong ham dong bat ngo (ma ' + c + ')'; reject(new Error(st.error)); }
      else if (wasRunning) log('warn', 'remote.close', 'Cong ho tro tu xa da dong (ma ' + c + ')');
    });
    proc.on('error', (e) => { if (!done) { done = true; st.error = String(e.message || e); reject(e); } });
    setTimeout(() => { if (!done) { done = true; try { proc && proc.kill(); } catch (e) {} st.error = 'Cho qua lau khong lay duoc dia chi (kiem tra mang)'; reject(new Error(st.error)); } }, 45000);
  });
}
function stop() {
  clearTimeout(offTimer); offTimer = null;
  const had = st.running;
  st.running = false; st.url = ''; st.code = ''; st.expires_at = null;
  try { if (proc) proc.kill(); } catch (e) {}
  proc = null;
  if (had) log('warn', 'remote.close', 'Da dong cong ho tro tu xa');
  return status();
}
// Request nay den TU BEN NGOAI (qua duong ham) hay tu may trong quan?
function isRemoteReq(req) {
  try {
    if (req.headers['cf-connecting-ip']) return true;
    const h = String(req.headers.host || '').split(':')[0].toLowerCase();
    return /\.trycloudflare\.com$/.test(h);
  } catch (e) { return false; }
}
module.exports = { start, stop, status, isRemoteReq, ensureTool, hasTool, setLogger, get code() { return st.code; }, get running() { return st.running; } };
